// Python-flavoured exception objects.
//
// The reference program lets exceptions escape to the top level, so the exact
// exception type name and message text are part of the observable behaviour.
// Every error raised anywhere in this port is one of these.

export class PyError extends Error {
  constructor(typeName, message = '') {
    super(message === '' ? typeName : `${typeName}: ${message}`);
    this.pyType = typeName;
    this.pyMessage = message;
    // Extra interpreter frames (innermost last) collected while unwinding,
    // used when rendering a traceback for code that ran inside eval().
    this.pyFrames = [];
  }

  // The final line of a traceback: "TypeError: msg", or bare "TypeError".
  get pyHeader() {
    return this.pyMessage === '' ? this.pyType : `${this.pyType}: ${this.pyMessage}`;
  }
}

const simple = (name) =>
  class extends PyError {
    constructor(message = '') {
      super(name, message);
    }
  };

export const PyTypeError = simple('TypeError');
export const PyValueError = simple('ValueError');
export const PyNameError = simple('NameError');
export const PyAttributeError = simple('AttributeError');
export const PyIndexError = simple('IndexError');
export const PyZeroDivisionError = simple('ZeroDivisionError');
export const PyOverflowError = simple('OverflowError');
export const PyRecursionError = simple('RecursionError');
export const PyMemoryError = simple('MemoryError');
export const PyStopIteration = simple('StopIteration');
export const PyUnicodeDecodeError = simple('UnicodeDecodeError');
export const PyUnicodeEncodeError = simple('UnicodeEncodeError');
export const PyNotImplementedError = simple('NotImplementedError');
export const PyArithmeticError = simple('ArithmeticError');

// KeyError's str() is the repr of the missing key, not a sentence.
export class PyKeyError extends PyError {
  constructor(reprOfKey) {
    super('KeyError', reprOfKey);
  }
}

// SyntaxError carries the location bits the traceback machinery prints as an
// extra source-echo block ('  File "<string>", line 1' + text + caret).
export class PySyntaxError extends PyError {
  constructor(message, { lineno = 1, offset = 1, endOffset = null, text = '', typeName = 'SyntaxError' } = {}) {
    super(typeName, message);
    this.lineno = lineno;
    this.offset = offset; // 1-based column, as Python reports it
    this.endOffset = endOffset;
    this.text = text;
  }
}

export class PyIndentationError extends PySyntaxError {
  constructor(message, loc = {}) {
    super(message, { ...loc, typeName: 'IndentationError' });
  }
}

// Raised for constructs this port deliberately does not implement. It is not a
// Python type; the entry point turns it into a diagnostic on stderr so a
// mismatch is never silently mistaken for real output.
export class UnsupportedError extends Error {
  constructor(message) {
    super(message);
    this.unsupported = true;
  }
}

export function notIterable(typeName) {
  return new PyTypeError(`'${typeName}' object is not iterable`);
}

export function notCallable(typeName) {
  return new PyTypeError(`'${typeName}' object is not callable`);
}

export function unsupportedBinary(op, left, right) {
  return new PyTypeError(`unsupported operand type(s) for ${op}: '${left}' and '${right}'`);
}

