// Python's repr() for floats.
//
// CPython prints the shortest decimal string that round-trips, then chooses
// fixed vs scientific notation from the decimal point position `decpt`:
//   use scientific  <=>  decpt <= -4 || decpt > 16
// In fixed notation a '.0' is appended when there would be no fraction; in
// scientific notation the mantissa keeps no trailing '.0' and the exponent is
// signed and zero-padded to at least two digits.
//
// JavaScript's Number#toExponential() with no argument already yields the
// shortest round-tripping digit string, which is the same digit string CPython
// gets from its dtoa in mode 0.

const DECPT_LOW = -4; // decpt <= -4  -> scientific
const DECPT_HIGH = 16; // decpt >  16  -> scientific

// Split |x| into its shortest round-tripping digits and decimal exponent.
// Returns { digits: "1234", decpt: n } meaning 0.1234... * 10**n.
function shortestDigits(abs) {
  const s = abs.toExponential(); // e.g. "1.25e+3", "5e-324"
  const m = /^(\d)(?:\.(\d+))?e([+-]\d+)$/.exec(s);
  if (m === null) {
    // Should be unreachable for finite, non-zero, positive input.
    throw new Error(`unexpected exponential form: ${s}`);
  }
  let digits = m[1] + (m[2] === undefined ? '' : m[2]);
  const exp10 = Number(m[3]);
  // Strip trailing zeros so "1.50e+1" style input cannot leak a stray digit.
  digits = digits.replace(/0+$/, '');
  if (digits === '') digits = '0';
  return { digits, decpt: exp10 + 1 };
}

function formatExponent(e) {
  const sign = e < 0 ? '-' : '+';
  const digits = String(Math.abs(e));
  return `e${sign}${digits.length < 2 ? '0' + digits : digits}`;
}

/**
 * Format a JS number the way Python's repr()/str() formats a float.
 *
 * @param {number} x
 * @param {boolean} addDotZero  Append '.0' to whole numbers in fixed notation.
 *   True for float repr ("2.0"); false inside complex repr ("(2+0j)").
 */
export function floatRepr(x, addDotZero = true) {
  if (Number.isNaN(x)) return 'nan';
  if (x === Infinity) return 'inf';
  if (x === -Infinity) return '-inf';

  const negative = x < 0 || Object.is(x, -0);
  const abs = Math.abs(x);

  let body;
  if (abs === 0) {
    body = addDotZero ? '0.0' : '0';
  } else {
    const { digits, decpt } = shortestDigits(abs);
    if (decpt <= DECPT_LOW || decpt > DECPT_HIGH) {
      const mantissa = digits.length > 1 ? `${digits[0]}.${digits.slice(1)}` : digits;
      body = mantissa + formatExponent(decpt - 1);
    } else if (decpt <= 0) {
      body = `0.${'0'.repeat(-decpt)}${digits}`;
    } else if (decpt >= digits.length) {
      body = digits + '0'.repeat(decpt - digits.length) + (addDotZero ? '.0' : '');
    } else {
      body = `${digits.slice(0, decpt)}.${digits.slice(decpt)}`;
    }
  }
  return negative ? `-${body}` : body;
}

// Python's str()/repr() for floats are identical.
export const floatStr = floatRepr;

