// The value model: how Python values are represented in JavaScript.
//
//   None        -> null
//   bool        -> true / false          (JS boolean)
//   int         -> BigInt                (arbitrary precision, like Python)
//   float       -> number                (IEEE-754 double, like Python)
//   str         -> string                (indexed by CODE POINT, see chars())
//   everything else -> one of the classes below
//
// Keeping int on BigInt and float on number is what makes `2` and `2.0` print
// differently without carrying a tag around.

import { PyTypeError, notIterable } from './errors.mjs';

export class PyBytes {
  constructor(data = []) {
    this.data = data instanceof Uint8Array ? data : Uint8Array.from(data);
  }
}

export class PyByteArray extends PyBytes {}

export class PyList {
  constructor(items = []) {
    this.items = items;
  }
}

export class PyTuple {
  constructor(items = []) {
    this.items = items;
  }
}

// Elements are held in CPython hash-table slot order (see setimpl.mjs), which
// is what iteration - and therefore flatten() - observes.
export class PySet {
  constructor(items = [], frozen = false) {
    this.items = items;
    this.frozen = frozen;
  }
}

export class PyDict {
  constructor(entries = []) {
    this.entries = entries; // [{ key, value }] in insertion order
  }

  get keys() {
    return this.entries.map((e) => e.key);
  }

  get values() {
    return this.entries.map((e) => e.value);
  }
}

export class PyDictView {
  constructor(dict, kind) {
    this.dict = dict;
    this.kind = kind; // 'keys' | 'values' | 'items'
  }
}

export class PyRange {
  constructor(start, stop, step) {
    this.start = start;
    this.stop = stop;
    this.step = step;
  }

  get length() {
    const { start, stop, step } = this;
    if (step > 0n) return stop > start ? (stop - start + step - 1n) / step : 0n;
    return start > stop ? (start - stop - step - 1n) / -step : 0n;
  }

  at(i) {
    return this.start + this.step * i;
  }
}

export class PyComplex {
  constructor(real, imag) {
    this.real = real;
    this.imag = imag;
  }
}

export class PySlice {
  constructor(start, stop, step) {
    this.start = start;
    this.stop = stop;
    this.step = step;
  }
}

export class PyEllipsisType {}
export const ELLIPSIS = new PyEllipsisType();

export class PyNotImplementedType {}
export const NOT_IMPLEMENTED = new PyNotImplementedType();

// Lazy iterators: generators, map/filter/zip/enumerate/reversed objects, ...
export class PyIterator {
  constructor(iterable, typeName = 'generator') {
    this.iterator = iterable[Symbol.iterator]();
    this.typeName = typeName;
    this.exhausted = false;
  }

  next() {
    if (this.exhausted) return { done: true, value: undefined };
    const step = this.iterator.next();
    if (step.done) this.exhausted = true;
    return step;
  }

  [Symbol.iterator]() {
    const self = this;
    return {
      next: () => self.next(),
      [Symbol.iterator]() {
        return this;
      },
    };
  }
}

export class PyMemoryView {
  constructor(source) {
    this.source = source; // PyBytes / PyByteArray
  }
}

// A user-level function created by `lambda`.
export class PyFunction {
  constructor(name, params, body, env) {
    this.name = name;
    this.params = params;
    this.body = body;
    this.env = env;
  }
}

// A builtin (len, print, ...) or a module-level Python function reachable from
// eval()'s globals (flatten, chunked). `reprText` overrides the default repr.
export class PyBuiltin {
  constructor(name, call, { typeName = 'builtin_function_or_method', reprText = null } = {}) {
    this.name = name;
    this.call = call;
    this.typeName = typeName;
    this.reprText = reprText;
  }
}

// A type object such as `list` or `int` - callable, and printed as <class 'x'>.
export class PyType {
  constructor(name, call) {
    this.name = name;
    this.call = call;
  }
}

export class PyModule {
  constructor(name, attrs = {}, file = null) {
    this.name = name;
    this.attrs = attrs;
    this.file = file;
  }
}

export class PyObjectLike {
  constructor(typeName, attrs = {}, reprText = null) {
    this.typeNameValue = typeName;
    this.attrs = attrs;
    this.reprText = reprText;
  }
}

/** Python's type(x).__name__. */
export function typeName(v) {
  if (v === null || v === undefined) return 'NoneType';
  switch (typeof v) {
    case 'boolean':
      return 'bool';
    case 'bigint':
      return 'int';
    case 'number':
      return 'float';
    case 'string':
      return 'str';
    default:
      break;
  }
  if (v instanceof PyByteArray) return 'bytearray';
  if (v instanceof PyBytes) return 'bytes';
  if (v instanceof PyList) return 'list';
  if (v instanceof PyTuple) return 'tuple';
  if (v instanceof PySet) return v.frozen ? 'frozenset' : 'set';
  if (v instanceof PyDict) return 'dict';
  if (v instanceof PyDictView) return `dict_${v.kind}`;
  if (v instanceof PyRange) return 'range';
  if (v instanceof PyComplex) return 'complex';
  if (v instanceof PySlice) return 'slice';
  if (v instanceof PyEllipsisType) return 'ellipsis';
  if (v instanceof PyNotImplementedType) return 'NotImplementedType';
  if (v instanceof PyIterator) return v.typeName;
  if (v instanceof PyMemoryView) return 'memoryview';
  if (v instanceof PyFunction) return 'function';
  if (v instanceof PyBuiltin) return v.typeName;
  if (v instanceof PyType) return 'type';
  if (v instanceof PyModule) return 'module';
  if (v instanceof PyObjectLike) return v.typeNameValue;
  return 'object';
}

/** Split a string into code points - Python strings are sequences of those. */
export function chars(s) {
  return Array.from(s);
}

export function strLen(s) {
  let n = 0;
  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);
    if (code >= 0xd800 && code <= 0xdbff && i + 1 < s.length) {
      const next = s.charCodeAt(i + 1);
      if (next >= 0xdc00 && next <= 0xdfff) i++;
    }
    n++;
  }
  return n;
}

/**
 * isinstance(v, collections.abc.Iterable) - i.e. does the type define
 * __iter__. This is exactly the test boltons' flatten uses.
 */
export function isIterable(v) {
  if (typeof v === 'string') return true;
  if (v === null || v === undefined) return false;
  return (
    v instanceof PyBytes ||
    v instanceof PyList ||
    v instanceof PyTuple ||
    v instanceof PySet ||
    v instanceof PyDict ||
    v instanceof PyDictView ||
    v instanceof PyRange ||
    v instanceof PyIterator ||
    v instanceof PyMemoryView
  );
}

/** str and bytes are the two iterables boltons' flatten refuses to descend. */
export function isStrOrBytes(v) {
  return typeof v === 'string' || (v instanceof PyBytes && !(v instanceof PyByteArray));
}

/** iter(v) -> a JS iterable, or TypeError with Python's wording. */
export function pyIter(v) {
  if (typeof v === 'string') return chars(v);
  if (v instanceof PyByteArray || v instanceof PyBytes) {
    return Array.from(v.data, (b) => BigInt(b));
  }
  if (v instanceof PyMemoryView) {
    return Array.from(v.source.data, (b) => BigInt(b));
  }
  if (v instanceof PyList || v instanceof PyTuple || v instanceof PySet) return v.items.slice();
  if (v instanceof PyDict) return v.keys;
  if (v instanceof PyDictView) {
    if (v.kind === 'keys') return v.dict.keys;
    if (v.kind === 'values') return v.dict.values;
    return v.dict.entries.map((e) => new PyTuple([e.key, e.value]));
  }
  if (v instanceof PyRange) {
    const out = [];
    const n = v.length;
    for (let i = 0n; i < n; i++) out.push(v.at(i));
    return out;
  }
  if (v instanceof PyIterator) return v;
  throw notIterable(typeName(v));
}

/** bool(v) */
export function truthy(v) {
  if (v === null || v === undefined) return false;
  if (typeof v === 'boolean') return v;
  if (typeof v === 'bigint') return v !== 0n;
  if (typeof v === 'number') return v !== 0;
  if (typeof v === 'string') return v.length > 0;
  if (v instanceof PyBytes) return v.data.length > 0;
  if (v instanceof PyList || v instanceof PyTuple || v instanceof PySet) return v.items.length > 0;
  if (v instanceof PyDict) return v.entries.length > 0;
  if (v instanceof PyDictView) return v.dict.entries.length > 0;
  if (v instanceof PyRange) return v.length > 0n;
  if (v instanceof PyComplex) return v.real !== 0 || v.imag !== 0;
  if (v instanceof PyMemoryView) return v.source.data.length > 0;
  return true;
}

function isNumberLike(v) {
  return typeof v === 'bigint' || typeof v === 'number' || typeof v === 'boolean' || v instanceof PyComplex;
}

function toComplex(v) {
  if (v instanceof PyComplex) return v;
  if (typeof v === 'boolean') return new PyComplex(v ? 1 : 0, 0);
  if (typeof v === 'bigint') return new PyComplex(Number(v), 0);
  return new PyComplex(v, 0);
}

function numericEq(a, b) {
  if (a instanceof PyComplex || b instanceof PyComplex) {
    const x = toComplex(a);
    const y = toComplex(b);
    // Compare the real parts exactly when both sides came from ints.
    return x.real === y.real && x.imag === y.imag;
  }
  const x = typeof a === 'boolean' ? (a ? 1n : 0n) : a;
  const y = typeof b === 'boolean' ? (b ? 1n : 0n) : b;
  if (typeof x === 'bigint' && typeof y === 'bigint') return x === y;
  if (typeof x === 'number' && typeof y === 'number') return x === y;
  // Mixed BigInt/number: JS `==` compares mathematical values exactly, which
  // is precisely Python's int/float comparison.
  // eslint-disable-next-line eqeqeq
  return x == y;
}

/** Python's `==`. */
export function pyEq(a, b) {
  if (a === b) return typeof a !== 'number' || !Number.isNaN(a);
  if (isNumberLike(a) && isNumberLike(b)) return numericEq(a, b);
  if (a === null || b === null) return false;
  if (typeof a === 'string' || typeof b === 'string') return a === b;
  if (a instanceof PyBytes && b instanceof PyBytes) {
    if (a instanceof PyByteArray !== b instanceof PyByteArray) {
      // bytes == bytearray compares by content in Python.
    }
    if (a.data.length !== b.data.length) return false;
    return a.data.every((byte, i) => byte === b.data[i]);
  }
  const seqA = a instanceof PyList ? a : a instanceof PyTuple ? a : null;
  const seqB = b instanceof PyList ? b : b instanceof PyTuple ? b : null;
  if (seqA && seqB) {
    if (a instanceof PyList !== b instanceof PyList) return false;
    if (seqA.items.length !== seqB.items.length) return false;
    return seqA.items.every((item, i) => pyEq(item, seqB.items[i]));
  }
  if (a instanceof PySet && b instanceof PySet) {
    if (a.items.length !== b.items.length) return false;
    return a.items.every((item) => b.items.some((other) => pyEq(item, other)));
  }
  if (a instanceof PyDict && b instanceof PyDict) {
    if (a.entries.length !== b.entries.length) return false;
    return a.entries.every((entry) =>
      b.entries.some((other) => pyEq(entry.key, other.key) && pyEq(entry.value, other.value)),
    );
  }
  if (a instanceof PyRange && b instanceof PyRange) {
    const la = a.length;
    if (la !== b.length) return false;
    if (la === 0n) return true;
    if (a.start !== b.start) return false;
    return la === 1n || a.step === b.step;
  }
  return false;
}

/** Stable fake addresses so reprs like <map object at 0x...> stay consistent. */
const addresses = new WeakMap();
let nextAddress = 0x7f3a1c000040n;
export function fakeAddress(obj) {
  let addr = addresses.get(obj);
  if (addr === undefined) {
    addr = nextAddress;
    nextAddress += 0x30n;
    addresses.set(obj, addr);
  }
  return `0x${addr.toString(16)}`;
}

export function asIndexable(v) {
  if (typeof v === 'bigint') return v;
  if (typeof v === 'boolean') return v ? 1n : 0n;
  throw new PyTypeError(
