    v instanceof PyBytes ||
    v instanceof PyList ||
    v instanceof PyTuple ||
    v instanceof PySet ||
    v instanceof PyDict ||
    v instanceof PyDictView ||
    v instanceof PyRange ||
    v instanceof PyIterator ||
    v instanceof PyMemoryView
