  if (v instanceof PyBytes) return v.data.length > 0;
  if (v instanceof PyList || v instanceof PyTuple || v instanceof PySet) return v.items.length > 0;
  if (v instanceof PyDict) return v.entries.length > 0;
  if (v instanceof PyDictView) return v.dict.entries.length > 0;
  if (v instanceof PyRange) return v.length > 0n;
