  if (v instanceof PyComplex) return v;
  if (typeof v === 'boolean') return new PyComplex(v ? 1 : 0, 0);
  if (typeof v === 'bigint') return new PyComplex(Number(v), 0);
  return new PyComplex(v, 0);
}

function numericEq(a, b) {
  if (a instanceof PyComplex || b instanceof PyComplex) {
    const x = toComplex(a);
    const y = toComplex(b);
    // Compare the real parts exactly when both sides came from ints.
    return x.real === y.real && x.imag === y.imag;
  }
  const x = typeof a === 'boolean' ? (a ? 1n : 0n) : a;
  const y = typeof b === 'boolean' ? (b ? 1n : 0n) : b;
