// CPython's hash() for the value kinds whose hash is *deterministic*.
//
// Why this exists: set iteration order (which flatten() observes) is decided by
// each element's hash, so reproducing Python's output for a set literal means
// reproducing Python's hashes bit for bit.
//
// str/bytes hashes are randomised per process (SipHash + PYTHONHASHSEED), so no
// deterministic answer exists for them; pyHash returns null in that case and the
// set builder falls back to insertion order. Unhashable types raise TypeError,
// exactly like Python.

import { PyTypeError } from './errors.mjs';
import {
  PyByteArray,
  PyBytes,
  PyComplex,
  PyDict,
  PyList,
  PySet,
  PyTuple,
  typeName,
} from './types.mjs';

const HASH_BITS = 61n;
export const HASH_MODULUS = (1n << HASH_BITS) - 1n; // 2**61 - 1
const HASH_INF = 314159n;
const HASH_IMAG = 1000003n;
const MASK64 = (1n << 64n) - 1n;

const XXPRIME_1 = 11400714785074694791n;
const XXPRIME_2 = 14029467366897019727n;
const XXPRIME_5 = 2870177450012600261n;

const NONE_HASH = 0xfca86420n; // constant since CPython 3.12

const u64 = (v) => v & MASK64;
const s64 = (v) => BigInt.asIntN(64, v);

/** frexp: v === m * 2**e with 0.5 <= |m| < 1. */
function frexp(v) {
  if (v === 0 || !Number.isFinite(v)) return [v, 0];
  const view = new DataView(new ArrayBuffer(8));
  view.setFloat64(0, v);
  let bits = view.getBigUint64(0);
  const rawExp = Number((bits >> 52n) & 0x7ffn);
  if (rawExp === 0) {
    // Subnormal: scale into the normal range, then correct the exponent.
    const [m, e] = frexp(v * 2 ** 64);
    return [m, e - 64];
  }
  bits = (bits & ~(0x7ffn << 52n)) | (1022n << 52n);
  view.setBigUint64(0, bits);
  return [view.getFloat64(0), rawExp - 1022];
}

/** hash() of a Python int. */
export function hashInt(value) {
  const negative = value < 0n;
  const magnitude = negative ? -value : value;
  let x = magnitude % HASH_MODULUS;
  if (negative) x = -x;
  return x === -1n ? -2n : x;
}

/** hash() of a Python float; null for nan (identity based since 3.10). */
export function hashFloat(value) {
  if (!Number.isFinite(value)) {
    if (Number.isNaN(value)) return null;
    return value > 0 ? HASH_INF : -HASH_INF;
  }
  let [m, e] = frexp(value);
  let sign = 1n;
  if (m < 0) {
    sign = -1n;
    m = -m;
  }
  let x = 0n;
  while (m !== 0) {
    x = ((x << 28n) & HASH_MODULUS) | (x >> (HASH_BITS - 28n));
    m *= 268435456.0; // 2**28
    e -= 28;
    const y = BigInt(Math.trunc(m));
    m -= Number(y);
    x += y;
    if (x >= HASH_MODULUS) x -= HASH_MODULUS;
  }
  const shift = BigInt(e >= 0 ? e % 61 : 60 - ((-1 - e) % 61));
  x = ((x << shift) & HASH_MODULUS) | (x >> (HASH_BITS - shift));
  if (sign === -1n) x = -x;
  return x === -1n ? -2n : x;
}

function shuffleBits(h) {
  return u64(u64(u64(h ^ 89869747n) ^ u64(h << 16n)) * 3644798167n);
}

function hashFrozenset(items) {
  let hash = 0n;
  for (const item of items) {
    const h = pyHash(item);
    if (h === null) return null;
    hash ^= shuffleBits(u64(h));
  }
  hash ^= u64((BigInt(items.length) + 1n) * 1927868237n);
  hash ^= u64(u64(hash >> 11n) ^ u64(hash >> 25n));
  hash = u64(u64(hash * 69069n) + 907133923n);
  const signed = s64(hash);
  return signed === -1n ? 590923713n : signed;
}

function hashTuple(items) {
  let acc = XXPRIME_5;
  for (const item of items) {
    const h = pyHash(item);
    if (h === null) return null;
    const lane = u64(h);
    acc = u64(acc + u64(lane * XXPRIME_2));
    acc = u64((acc << 31n) | (acc >> 33n)); // XXROTATE
    acc = u64(acc * XXPRIME_1);
  }
  acc = u64(acc + u64(BigInt(items.length) ^ u64(XXPRIME_5 ^ 3527539n)));
  const signed = s64(acc);
  return signed === -1n ? 1546275796n : signed;
}

/**
 * hash(value), or null when Python's answer is not reproducible (str, bytes,
 * nan, and anything containing them). Raises TypeError for unhashable types.
 */
export function pyHash(value) {
  if (value === null || value === undefined) return NONE_HASH;
  switch (typeof value) {
    case 'boolean':
      return value ? 1n : 0n;
    case 'bigint':
      return hashInt(value);
    case 'number':
      return hashFloat(value);
    case 'string':
      return null; // SipHash with a per-process key
    default:
      break;
  }
  if (value instanceof PyByteArray) throw new PyTypeError("unhashable type: 'bytearray'");
  if (value instanceof PyBytes) return null; // also SipHash
  if (value instanceof PyList) throw new PyTypeError("unhashable type: 'list'");
  if (value instanceof PyDict) throw new PyTypeError("unhashable type: 'dict'");
  if (value instanceof PySet) {
    if (!value.frozen) throw new PyTypeError("unhashable type: 'set'");
    return hashFrozenset(value.items);
  }
  if (value instanceof PyTuple) return hashTuple(value.items);
  if (value instanceof PyComplex) {
    const hr = hashFloat(value.real);
    const hi = hashFloat(value.imag);
    if (hr === null || hi === null) return null;
    const combined = u64(u64(hr) + u64(HASH_IMAG * u64(hi)));
    const signed = s64(combined);
    return signed === -1n ? -2n : signed;
  }
  // Everything else uses object identity, which is address based.
  return null;
}

/** Does Python consider this value hashable at all? */
export function isHashable(value) {
  try {
    pyHash(value);
    return true;
  } catch (err) {
    if (err instanceof PyTypeError) return false;
    throw err;
  }
}

export function unhashableError(value) {
  return new PyTypeError(`unhashable type: '${typeName(value)}'`);
}

