// A faithful port of CPython's set hash table, purely so that iteration order
// matches. flatten() iterates sets, so `{16,8,4,2,1}` must come out in exactly
// the order CPython's open-addressing table produces: [16, 1, 2, 4, 8].
//
// Two construction paths exist in CPython and they give DIFFERENT orders:
//
//  * A set display whose elements are all compile-time constants is compiled to
//    a frozenset constant plus `BUILD_SET 0; SET_UPDATE 1`. The frozenset is
//    filled element by element (with incremental resizes), then merged into a
//    fresh empty set - a second rehash that changes the order.
//  * Anything else (set(iterable), a display with a non-constant element) is
//    filled element by element into one table.
//
// Both are implemented below; the interpreter picks the path CPython would.

import { pyEq } from './types.mjs';
import { pyHash } from './hash.mjs';

const MINSIZE = 8;
const LINEAR_PROBES = 9;
const PERTURB_SHIFT = 5n;
const MASK64 = (1n << 64n) - 1n;
const GROWTH_THRESHOLD = 50000; // above this CPython grows by 2x, not 4x

class SetTable {
  constructor(size = MINSIZE) {
    this.slots = new Array(size).fill(null);
    this.mask = size - 1;
    this.fill = 0;
    this.used = 0;
  }

  /** set_add_entry(): probe, insert if absent, then maybe grow. */
  add(key, hash) {
    const uhash = BigInt.asUintN(64, hash);
    const bigMask = BigInt(this.mask);
    let i = Number(uhash & bigMask);
    let perturb = uhash;
    for (;;) {
      const probes = i + LINEAR_PROBES <= this.mask ? LINEAR_PROBES : 0;
      for (let j = 0; j <= probes; j++) {
        const entry = this.slots[i + j];
        if (entry === null) {
          this.slots[i + j] = { key, hash };
          this.fill += 1;
          this.used += 1;
          this.maybeGrow();
          return;
        }
        if (entry.hash === hash && pyEq(entry.key, key)) return; // already present
      }
      perturb >>= PERTURB_SHIFT;
      i = Number(((BigInt(i) * 5n + 1n + perturb) & MASK64) & bigMask);
    }
  }

  /** set_insert_clean(): the key is known absent and no slot is a dummy. */
  insertClean(key, hash) {
    const uhash = BigInt.asUintN(64, hash);
    const bigMask = BigInt(this.mask);
    let i = Number(uhash & bigMask);
    let perturb = uhash;
    for (;;) {
      const probes = i + LINEAR_PROBES <= this.mask ? LINEAR_PROBES : 0;
      for (let j = 0; j <= probes; j++) {
        if (this.slots[i + j] === null) {
          this.slots[i + j] = { key, hash };
          return;
        }
      }
      perturb >>= PERTURB_SHIFT;
      i = Number(((BigInt(i) * 5n + 1n + perturb) & MASK64) & bigMask);
    }
  }

  maybeGrow() {
    if (this.fill * 5 < this.mask * 3) return;
    this.resize(this.used > GROWTH_THRESHOLD ? this.used * 2 : this.used * 4);
  }

  /** set_table_resize(): smallest power of two strictly greater than minused. */
  resize(minused) {
    let newsize = MINSIZE;
    while (newsize <= minused) newsize <<= 1;
    const old = this.slots;
    this.slots = new Array(newsize).fill(null);
    this.mask = newsize - 1;
    this.fill = this.used;
    for (const entry of old) {
      if (entry !== null) this.insertClean(entry.key, entry.hash);
    }
