  /** set_merge(): the empty-target fast path keeps the source's slot order. */
  merge(other) {
    if (other.used === 0) return;
    if ((this.fill + other.used) * 5 >= this.mask * 3) {
      this.resize((this.used + other.used) * 2);
    }
    if (this.fill === 0) {
      this.fill = other.used;
      this.used = other.used;
      for (const entry of other.slots) {
        if (entry !== null) this.insertClean(entry.key, entry.hash);
      }
      return;
    }
    for (const entry of other.slots) {
      if (entry !== null) this.add(entry.key, entry.hash);
    }
  }

  /** Iteration order: ascending slot index. */
  order() {
    const out = [];
    for (const entry of this.slots) {
      if (entry !== null) out.push(entry.key);
    }
    return out;
  }
