 * Hash every value up front. Returns null when any hash is unreproducible
 * (str/bytes/nan), in which case we cannot know Python's order.
 */
function hashAll(values) {
  const hashes = [];
  for (const value of values) {
    const h = pyHash(value); // throws TypeError for unhashable values
    if (h === null) return null;
    hashes.push(h);
  }
  return hashes;
