// repr() and str(), which together decide every character the program prints.

import { floatRepr } from './floatrepr.mjs';
import {
  ELLIPSIS,
  PyBuiltin,
  PyByteArray,
  PyBytes,
  PyComplex,
  PyDict,
  PyDictView,
  PyEllipsisType,
  PyFunction,
  PyIterator,
  PyList,
  PyMemoryView,
  PyModule,
  PyNotImplementedType,
  PyObjectLike,
  PyRange,
  PySet,
  PySlice,
  PyTuple,
  PyType,
  chars,
  fakeAddress,
  typeName,
} from './types.mjs';

// Python's str.isprintable(): false for the Unicode "Other" and "Separator"
// categories, except for the ASCII space.
const NONPRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

function isPrintable(ch) {
  if (ch === ' ') return true;
  return !NONPRINTABLE.test(ch);
}

function hex2(n) {
  return n.toString(16).padStart(2, '0');
}

function escapeNonPrintable(ch) {
  const cp = ch.codePointAt(0);
  if (cp < 0x100) return `\\x${hex2(cp)}`;
  if (cp < 0x10000) return `\\u${cp.toString(16).padStart(4, '0')}`;
  return `\\U${cp.toString(16).padStart(8, '0')}`;
}

/** repr() of a str, following CPython's unicode_repr(). */
export function strRepr(s) {
  const quote = s.includes("'") && !s.includes('"') ? '"' : "'";
  let out = quote;
  for (const ch of chars(s)) {
    if (ch === quote || ch === '\\') {
      out += `\\${ch}`;
      continue;
    }
    if (ch === '\t') {
      out += '\\t';
      continue;
    }
    if (ch === '\n') {
      out += '\\n';
      continue;
    }
    if (ch === '\r') {
      out += '\\r';
      continue;
    }
    const cp = ch.codePointAt(0);
    if (cp < 0x20 || cp === 0x7f) {
      out += `\\x${hex2(cp)}`;
      continue;
    }
    if (cp < 0x7f) {
      out += ch;
      continue;
    }
    out += isPrintable(ch) ? ch : escapeNonPrintable(ch);
  }
  return out + quote;
}

/** repr() of bytes, following CPython's PyBytes_Repr(). */
export function bytesRepr(data) {
  const hasSingle = data.includes(0x27);
  const hasDouble = data.includes(0x22);
  const quote = hasSingle && !hasDouble ? 0x22 : 0x27;
  let out = `b${String.fromCharCode(quote)}`;
  for (const byte of data) {
    if (byte === quote || byte === 0x5c) {
      out += `\\${String.fromCharCode(byte)}`;
    } else if (byte === 0x09) {
      out += '\\t';
    } else if (byte === 0x0a) {
      out += '\\n';
    } else if (byte === 0x0d) {
      out += '\\r';
    } else if (byte < 0x20 || byte >= 0x7f) {
      out += `\\x${hex2(byte)}`;
    } else {
      out += String.fromCharCode(byte);
    }
  }
  return out + String.fromCharCode(quote);
}

/** repr() of a complex; note the parts carry no forced '.0'. */
export function complexRepr(value) {
  const { real, imag } = value;
  if (real === 0 && !Object.is(real, -0)) {
    return `${floatRepr(imag, false)}j`;
  }
  const imagPart = floatRepr(imag, false);
  const sign = imagPart.startsWith('-') ? '' : '+';
  return `(${floatRepr(real, false)}${sign}${imagPart}j)`;
}

export function pyRepr(value) {
  if (value === null || value === undefined) return 'None';
  switch (typeof value) {
    case 'boolean':
      return value ? 'True' : 'False';
    case 'bigint':
      return value.toString();
    case 'number':
      return floatRepr(value);
    case 'string':
      return strRepr(value);
    default:
      break;
  }
  if (value instanceof PyByteArray) return `bytearray(${bytesRepr(value.data)})`;
  if (value instanceof PyBytes) return bytesRepr(value.data);
  if (value instanceof PyList) return `[${value.items.map(pyRepr).join(', ')}]`;
  if (value instanceof PyTuple) {
    if (value.items.length === 1) return `(${pyRepr(value.items[0])},)`;
    return `(${value.items.map(pyRepr).join(', ')})`;
  }
