    const body = value.items.map(pyRepr).join(', ');
    if (value.frozen) return value.items.length === 0 ? 'frozenset()' : `frozenset({${body}})`;
    return value.items.length === 0 ? 'set()' : `{${body}}`;
  }
  if (value instanceof PyDict) {
    return `{${value.entries.map((e) => `${pyRepr(e.key)}: ${pyRepr(e.value)}`).join(', ')}}`;
  }
  if (value instanceof PyDictView) {
    const items =
      value.kind === 'keys'
        ? value.dict.keys
        : value.kind === 'values'
          ? value.dict.values
          : value.dict.entries.map((e) => new PyTuple([e.key, e.value]));
    return `dict_${value.kind}([${items.map(pyRepr).join(', ')}])`;
  }
  if (value instanceof PyRange) {
    if (value.step === 1n) return `range(${value.start}, ${value.stop})`;
    return `range(${value.start}, ${value.stop}, ${value.step})`;
  }
  if (value instanceof PyComplex) return complexRepr(value);
  if (value instanceof PySlice) {
    return `slice(${pyRepr(value.start)}, ${pyRepr(value.stop)}, ${pyRepr(value.step)})`;
  }
  if (value instanceof PyEllipsisType) return 'Ellipsis';
  if (value instanceof PyNotImplementedType) return 'NotImplemented';
  if (value instanceof PyMemoryView) return `<memory at ${fakeAddress(value)}>`;
  if (value instanceof PyIterator) {
    if (value.typeName === 'generator') {
      return `<generator object ${value.qualname ?? '<genexpr>'} at ${fakeAddress(value)}>`;
    }
    return `<${value.typeName} object at ${fakeAddress(value)}>`;
  }
  if (value instanceof PyFunction) {
    return `<function ${value.name} at ${fakeAddress(value)}>`;
  }
  if (value instanceof PyBuiltin) {
    return value.reprText ?? `<built-in function ${value.name}>`;
  }
  if (value instanceof PyType) return `<class '${value.name}'>`;
  if (value instanceof PyModule) {
    return value.file === null
      ? `<module '${value.name}'>`
      : `<module '${value.name}' from '${value.file}'>`;
  }
  if (value instanceof PyObjectLike) {
    return value.reprText ?? `<${value.typeNameValue} object at ${fakeAddress(value)}>`;
  }
  return `<${typeName(value)} object at ${fakeAddress(value)}>`;
}

/** str(): identical to repr() except that a str is returned unquoted. */
export function pyStr(value) {
  return typeof value === 'string' ? value : pyRepr(value);
}

export { ELLIPSIS };

