export function toFloat(v) {
  if (typeof v === 'number') return v;
  const asBig = asInt(v);
  if (typeof asBig === 'bigint') {
    const f = Number(asBig);
    if (!Number.isFinite(f)) throw new PyOverflowError('int too large to convert to float');
    return f;
  }
