export function toComplex(v) {
  if (v instanceof PyComplex) return v;
  return new PyComplex(toFloat(v), 0);
}

export function bigFloorDiv(a, b) {
  let q = a / b;
  if (a % b !== 0n && a < 0n !== b < 0n) q -= 1n;
  return q;
}

export function bigMod(a, b) {
  const r = a % b;
  if (r !== 0n && r < 0n !== b < 0n) return r + b;
  return r;
}

