// Binary / unary operator dispatch: numbers first, then the sequence and set
// protocols, then Python's TypeError wording. `x*2` in the source script lands
// in binaryOp('*', x, 2n).

import { PyMemoryError, PyTypeError, PyValueError, unsupportedBinary } from './errors.mjs';
import {
  PyByteArray,
  PyBytes,
  PyDict,
  PyDictView,
  PyList,
  PyRange,
  PySet,
  PyTuple,
  chars,
  isIterable,
  pyEq,
  pyIter,
  strLen,
  truthy,
  typeName,
} from './types.mjs';
import { asInt, isInt, isNumeric, numericBinary, numericCompare, numericInvert, numericNegate, numericPositive } from './numeric.mjs';
import { setElementOrder } from './setimpl.mjs';
import { percentFormat } from './strformat.mjs';

const MAX_SEQUENCE = 100000000; // stand-in for Python running out of memory

function repeatCount(v) {
  if (!isInt(v)) {
    throw new PyTypeError(`can't multiply sequence by non-int of type '${typeName(v)}'`);
  }
  const n = asInt(v);
  return n < 0n ? 0n : n;
}

function guardLength(n) {
  if (n > BigInt(MAX_SEQUENCE)) throw new PyMemoryError('');
  return Number(n);
}

function repeatSequence(seq, times) {
  const n = repeatCount(times);
  const count = guardLength(n * BigInt(seq.length || 1));
  void count;
  const out = [];
  for (let i = 0n; i < n; i++) out.push(...seq);
  return out;
}

function isSet(v) {
  return v instanceof PySet;
}

function setBinary(op, left, right) {
  const a = left.items;
  const b = right.items;
  const has = (items, value) => items.some((item) => pyEq(item, value));
  let values;
  switch (op) {
    case '|':
      values = [...a, ...b.filter((x) => !has(a, x))];
      break;
    case '&':
      values = a.filter((x) => has(b, x));
      break;
    case '-':
      values = a.filter((x) => !has(b, x));
      break;
    case '^':
      values = [...a.filter((x) => !has(b, x)), ...b.filter((x) => !has(a, x))];
      break;
    default:
      throw unsupportedBinary(op, typeName(left), typeName(right));
  }
  return new PySet(setElementOrder(values), left.frozen && right.frozen);
}

export function binaryOp(op, left, right) {
  const numeric = numericBinary(op, left, right);
  if (numeric !== undefined) return numeric;

  if (op === '*') {
    if (typeof left === 'string') return left.repeat(guardLength(repeatCount(right) * BigInt(strLen(left) || 1)) && Number(repeatCount(right)));
    if (typeof right === 'string') return binaryOp('*', right, left);
    if (left instanceof PyBytes) {
      const data = repeatSequence(Array.from(left.data), right);
      return left instanceof PyByteArray ? new PyByteArray(data) : new PyBytes(data);
    }
    if (right instanceof PyBytes) return binaryOp('*', right, left);
    if (left instanceof PyList) return new PyList(repeatSequence(left.items, right));
    if (right instanceof PyList) return binaryOp('*', right, left);
    if (left instanceof PyTuple) return new PyTuple(repeatSequence(left.items, right));
    if (right instanceof PyTuple) return binaryOp('*', right, left);
  }

  if (op === '+') {
    if (typeof left === 'string') {
      if (typeof right !== 'string') {
        throw new PyTypeError(`can only concatenate str (not "${typeName(right)}") to str`);
      }
      return left + right;
    }
    if (left instanceof PyList) {
      if (!(right instanceof PyList)) {
        throw new PyTypeError(`can only concatenate list (not "${typeName(right)}") to list`);
      }
      return new PyList([...left.items, ...right.items]);
    }
    if (left instanceof PyTuple) {
      if (!(right instanceof PyTuple)) {
        throw new PyTypeError(`can only concatenate tuple (not "${typeName(right)}") to tuple`);
      }
      return new PyTuple([...left.items, ...right.items]);
    }
    if (left instanceof PyBytes) {
      if (!(right instanceof PyBytes)) {
        throw new PyTypeError(`can't concat ${typeName(right)} to ${typeName(left)}`);
      }
      const data = new Uint8Array(left.data.length + right.data.length);
      data.set(left.data, 0);
      data.set(right.data, left.data.length);
      return left instanceof PyByteArray ? new PyByteArray(data) : new PyBytes(data);
    }
  }

  if (op === '%' && typeof left === 'string') return percentFormat(left, right);

  if (isSet(left) && isSet(right)) return setBinary(op, left, right);

  if (op === '|' && left instanceof PyDict && right instanceof PyDict) {
    const merged = new PyDict(left.entries.map((e) => ({ ...e })));
    for (const entry of right.entries) {
      const existing = merged.entries.find((e) => pyEq(e.key, entry.key));
      if (existing) existing.value = entry.value;
      else merged.entries.push({ ...entry });
    }
    return merged;
  }

  throw unsupportedBinary(op, typeName(left), typeName(right));
}

export function unaryOp(op, value) {
  switch (op) {
    case '-':
      if (!isNumeric(value)) throw new PyTypeError(`bad operand type for unary -: '${typeName(value)}'`);
      return numericNegate(value);
    case '+':
      if (!isNumeric(value)) throw new PyTypeError(`bad operand type for unary +: '${typeName(value)}'`);
      return numericPositive(value);
    case '~':
      return numericInvert(value);
    case 'not':
      return !truthy(value);
    default:
      throw new PyTypeError(`unsupported unary operator ${op}`);
  }
}

function sequenceItems(v) {
  if (typeof v === 'string') return chars(v);
  if (v instanceof PyBytes) return Array.from(v.data, (b) => BigInt(b));
  if (v instanceof PyList || v instanceof PyTuple) return v.items;
  return null;
}

/** Lexicographic ordering for the types Python can order. */
function orderedCompare(op, left, right) {
  if (isNumeric(left) && isNumeric(right)) {
    const cmp = numericCompare(left, right);
    if (Number.isNaN(cmp)) {
      if (left instanceof Object || right instanceof Object) {
        throw new PyTypeError(
          `'${op}' not supported between instances of '${typeName(left)}' and '${typeName(right)}'`,
        );
      }
      return false;
    }
    return applyCompare(op, cmp);
  }
  if (typeof left === 'string' && typeof right === 'string') {
    const a = chars(left);
    const b = chars(right);
    return applyCompare(op, compareCodePointArrays(a, b));
  }
  const seqA = sequenceItems(left);
  const seqB = sequenceItems(right);
  const sameKind =
    (left instanceof PyList && right instanceof PyList) ||
    (left instanceof PyTuple && right instanceof PyTuple) ||
    (left instanceof PyBytes && right instanceof PyBytes);
  if (seqA && seqB && sameKind) {
    return applyCompare(op, compareSequences(seqA, seqB));
  }
  if (isSet(left) && isSet(right)) return applyCompare(op, compareSets(op, left, right));
  throw new PyTypeError(
    `'${op}' not supported between instances of '${typeName(left)}' and '${typeName(right)}'`,
  );
}

function compareCodePointArrays(a, b) {
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    const x = a[i].codePointAt(0);
    const y = b[i].codePointAt(0);
    if (x !== y) return x < y ? -1 : 1;
  }
  return a.length === b.length ? 0 : a.length < b.length ? -1 : 1;
}

function compareSequences(a, b) {
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    if (!pyEq(a[i], b[i])) {
      return orderedCompare('<', a[i], b[i]) ? -1 : 1;
    }
  }
  return a.length === b.length ? 0 : a.length < b.length ? -1 : 1;
}

function compareSets(op, left, right) {
  const has = (items, value) => items.some((item) => pyEq(item, value));
  const subset = left.items.every((item) => has(right.items, item));
  const superset = right.items.every((item) => has(left.items, item));
  if (subset && superset) return 0;
  if (subset) return -1;
  if (superset) return 1;
  // Incomparable sets: every ordering comparison is False.
  return NaN;
}

function applyCompare(op, cmp) {
  if (Number.isNaN(cmp)) return false;
  switch (op) {
    case '<':
      return cmp < 0;
    case '<=':
      return cmp <= 0;
    case '>':
      return cmp > 0;
    case '>=':
      return cmp >= 0;
    default:
      throw new PyTypeError(`unsupported comparison ${op}`);
  }
}

export function compareOp(op, left, right) {
  switch (op) {
    case '==':
      return pyEq(left, right);
    case '!=':
      return !pyEq(left, right);
    case 'is':
      return pyIs(left, right);
    case 'is not':
      return !pyIs(left, right);
    case 'in':
      return containsOp(right, left);
    case 'not in':
      return !containsOp(right, left);
    default:
      return orderedCompare(op, left, right);
  }
}

/**
 * `is` compares identity. Small ints, short strings, None, True/False and the
 * empty tuple are interned by CPython, so identity coincides with equality for
 * the values eval() can produce here.
 */
export function pyIs(left, right) {
  if (left === null || right === null) return left === right;
  if (typeof left === 'boolean' || typeof right === 'boolean') return left === right;
  if (typeof left === 'bigint' && typeof right === 'bigint') {
    return left === right && left >= -5n && left <= 256n;
  }
  if (typeof left === 'number' && typeof right === 'number') return false;
  if (typeof left === 'string' && typeof right === 'string') {
    return left === right && /^[A-Za-z0-9_]*$/.test(left);
  }
  return left === right;
}

export function containsOp(container, value) {
  if (typeof container === 'string') {
    if (typeof value !== 'string') {
      throw new PyTypeError(
        `'in <string>' requires string as left operand, not ${typeName(value)}`,
      );
    }
    return container.includes(value);
  }
  if (container instanceof PyDict) return container.keys.some((key) => pyEq(key, value));
  if (container instanceof PyDictView) {
    return pyIter(container).some
      ? Array.from(pyIter(container)).some((item) => pyEq(item, value))
      : false;
  }
  if (container instanceof PyRange) {
    if (!isNumeric(value)) return false;
    for (const item of pyIter(container)) if (pyEq(item, value)) return true;
    return false;
  }
  if (container instanceof PyBytes) {
    if (isInt(value)) {
      const n = asInt(value);
      if (n < 0n || n > 255n) throw new PyValueError('byte must be in range(0, 256)');
      return Array.from(container.data).some((b) => BigInt(b) === n);
    }
    if (value instanceof PyBytes) {
      const haystack = Array.from(container.data).join(',');
      const needle = Array.from(value.data).join(',');
      return needle === '' || haystack.includes(needle);
    }
    throw new PyTypeError(
      `a bytes-like object is required, not '${typeName(value)}'`,
    );
  }
  if (!isIterable(container)) {
    throw new PyTypeError(`argument of type '${typeName(container)}' is not iterable`);
  }
  for (const item of pyIter(container)) {
    if (pyEq(item, value)) return true;
  }
  return false;
}

