// String formatting: the `%` operator and the format-spec mini language used by
// f-strings and format(). Only the parts that can plausibly appear inside an
// eval'd expression are implemented; anything else raises the same ValueError
// Python would for an unknown spec.

import { PyTypeError, PyValueError } from './errors.mjs';
import { floatRepr } from './floatrepr.mjs';
import { PyDict, PyList, PyTuple, chars, strLen, typeName } from './types.mjs';
import { asInt, isInt, toFloat } from './numeric.mjs';
import { pyRepr, pyStr } from './repr.mjs';

function roundHalfEven(value, digits) {
  // toFixed rounds half away from zero for exactly-representable ties; Python
  // uses the correctly-rounded decimal conversion, which for doubles means
  // ties-to-even on the *binary* value. toFixed on a double already reflects
  // the binary value, so it agrees except for exact .5 ties.
  const scaled = value * 10 ** digits;
  if (Number.isInteger(scaled * 2) && !Number.isInteger(scaled)) {
    const floor = Math.floor(scaled);
    const even = floor % 2 === 0 ? floor : floor + 1;
    return (even / 10 ** digits).toFixed(digits);
  }
  return value.toFixed(digits);
}

function fixed(value, precision) {
  if (!Number.isFinite(value)) return value > 0 ? 'inf' : Number.isNaN(value) ? 'nan' : '-inf';
  return roundHalfEven(value, precision);
}

function scientific(value, precision, upper) {
  if (!Number.isFinite(value)) return fixed(value, precision);
  let s = value.toExponential(precision);
  // Python pads the exponent to at least two digits.
  s = s.replace(/e([+-])(\d)$/, 'e$10$2');
  return upper ? s.toUpperCase() : s;
}

function general(value, precision, upper) {
  if (!Number.isFinite(value)) return fixed(value, precision);
  const p = precision === 0 ? 1 : precision;
  const exp = value === 0 ? 0 : Math.floor(Math.log10(Math.abs(value)));
  let s;
  if (exp < -4 || exp >= p) {
    s = scientific(value, p - 1, false);
    // Strip trailing zeros in the mantissa, as %g does.
    s = s.replace(/\.?0+e/, 'e');
  } else {
    s = fixed(value, Math.max(p - 1 - exp, 0));
    if (s.includes('.')) s = s.replace(/\.?0+$/, '');
  }
  return upper ? s.toUpperCase() : s;
}

function groupThousands(digits, separator) {
  let out = '';
  for (let i = 0; i < digits.length; i++) {
    if (i > 0 && (digits.length - i) % 3 === 0) out += separator;
    out += digits[i];
  }
  return out;
}

const SPEC_RE = /^(?:(.)?([<>=^]))?([+\- ])?(z)?(#)?(0)?(\d+)?([,_])?(?:\.(\d+))?([bcdeEfFgGnosxX%])?$/;

/** format(value, spec) for the subset of the spec language we support. */
export function formatValue(value, spec) {
  if (spec === '') return pyStr(value);
  const m = SPEC_RE.exec(spec);
  if (m === null) throw new PyValueError(`Invalid format specifier '${spec}' for object of type '${typeName(value)}'`);
  const [, fillRaw, alignRaw, sign, , alt, zero, widthRaw, grouping, precisionRaw, typeRaw] = m;
  const width = widthRaw === undefined ? 0 : Number(widthRaw);
  const precision = precisionRaw === undefined ? null : Number(precisionRaw);
  const type = typeRaw ?? (isInt(value) ? 'd' : typeof value === 'number' ? null : 's');
  let fill = fillRaw ?? (zero ? '0' : ' ');
  let align = alignRaw ?? (zero ? '=' : isInt(value) || typeof value === 'number' ? '>' : '<');

  let body;
  let signPart = '';
  if (type === 's' || type === null) {
    if (type === 's' && typeof value !== 'string') {
      if (isInt(value) || typeof value === 'number') {
        throw new PyValueError(`Unknown format code 's' for object of type '${typeName(value)}'`);
      }
    }
    body = pyStr(value);
    if (precision !== null) body = chars(body).slice(0, precision).join('');
  } else if ('bcdoxX'.includes(type)) {
    if (!isInt(value)) {
      throw new PyValueError(`Unknown format code '${type}' for object of type '${typeName(value)}'`);
    }
    let n = asInt(value);
    if (n < 0n) {
      signPart = '-';
      n = -n;
    } else if (sign === '+') signPart = '+';
    else if (sign === ' ') signPart = ' ';
    const radix = type === 'b' ? 2 : type === 'o' ? 8 : type === 'd' ? 10 : 16;
    if (type === 'c') body = String.fromCodePoint(Number(n));
    else body = n.toString(radix);
    if (type === 'X') body = body.toUpperCase();
    if (grouping && type === 'd') body = groupThousands(body, grouping === ',' ? ',' : '_');
    if (alt) body = { b: '0b', o: '0o', x: '0x', X: '0X', d: '' }[type] + body;
  } else {
    const f = toFloat(value);
    const magnitude = Math.abs(f);
    if (f < 0 || Object.is(f, -0)) signPart = '-';
    else if (sign === '+') signPart = '+';
    else if (sign === ' ') signPart = ' ';
    const p = precision === null ? 6 : precision;
    if (type === 'f' || type === 'F') body = fixed(magnitude, p);
    else if (type === 'e' || type === 'E') body = scientific(magnitude, p, type === 'E');
    else if (type === '%') body = `${fixed(magnitude * 100, p)}%`;
    else if (type === 'g' || type === 'G' || type === 'n') {
      body = general(magnitude, precision === null ? 6 : precision, type === 'G');
    } else {
      throw new PyValueError(`Unknown format code '${type}' for object of type '${typeName(value)}'`);
    }
    if (grouping) {
      const dot = body.indexOf('.');
      const intPart = dot === -1 ? body : body.slice(0, dot);
      const rest = dot === -1 ? '' : body.slice(dot);
      body = groupThousands(intPart, grouping === ',' ? ',' : '_') + rest;
    }
  }

  const text = signPart + body;
  if (text.length >= width) return text;
  const pad = width - strLen(text);
  if (align === '<') return text + fill.repeat(pad);
  if (align === '>') return fill.repeat(pad) + text;
  if (align === '=') return signPart + fill.repeat(pad) + body;
  const left = Math.floor(pad / 2);
  return fill.repeat(left) + text + fill.repeat(pad - left);
}

const CONVERSION_RE = /%(?:\(([^)]*)\))?([-+ #0]*)(\d+|\*)?(?:\.(\d+|\*))?[hlL]?([diouxXeEfFgGcrsab%])/g;

/** The `%` operator on strings. */
export function percentFormat(template, argument) {
  const mapping = argument instanceof PyDict ? argument : null;
  let args;
  if (mapping !== null) args = [];
  else if (argument instanceof PyTuple) args = argument.items.slice();
  else args = [argument];

  let index = 0;
  const takeArg = () => {
    if (index >= args.length) throw new PyTypeError('not enough arguments for format string');
    return args[index++];
  };

  let consumedAll = false;
  const out = template.replace(CONVERSION_RE, (match, key, flags, widthSpec, precisionSpec, conv) => {
    if (conv === '%') return '%';
    let value;
    if (key !== undefined) {
      if (mapping === null) throw new PyTypeError('format requires a mapping');
      const entry = mapping.entries.find((e) => e.key === key);
      if (entry === undefined) throw new PyTypeError(`'${key}'`);
      value = entry.value;
    } else {
      value = takeArg();
    }
    const width = widthSpec === '*' ? Number(asInt(takeArg())) : widthSpec ? Number(widthSpec) : 0;
    const precision =
      precisionSpec === '*' ? Number(asInt(takeArg())) : precisionSpec !== undefined ? Number(precisionSpec) : null;

    let body;
    switch (conv) {
      case 'd':
      case 'i':
      case 'u':
        body = formatValue(isInt(value) ? value : BigInt(Math.trunc(toFloat(value))), 'd');
        break;
      case 'o':
      case 'x':
      case 'X':
        body = formatValue(value, conv);
        break;
      case 'e':
      case 'E':
      case 'f':
      case 'F':
      case 'g':
      case 'G':
        body = formatValue(toFloat(value), `.${precision === null ? 6 : precision}${conv}`);
        break;
      case 'c':
        body = typeof value === 'string' ? value : String.fromCodePoint(Number(asInt(value)));
        break;
      case 'r':
        body = pyRepr(value);
        break;
      case 's':
        body = pyStr(value);
        break;
      case 'a':
        body = pyRepr(value);
        break;
      default:
