// here). The traceback the reference program prints on a bad argument shows the
// call chain flatten -> flatten_iter, which is mirrored by frame labels in
// traceback.mjs.

import { PyTypeError, PyValueError } from '../errors.mjs';
import {
  PyBytes,
  PyList,
  isIterable,
  isStrOrBytes,
  pyIter,
} from '../types.mjs';

/** boltons.iterutils.is_iterable: does iter(obj) work. */
export function isIterableValue(value) {
  return isIterable(value);
}

/**
 * flatten_iter: descend into every iterable except str and bytes.
 *
 * The argument itself is always iterated - flatten('abc') yields 'a','b','c' -
 * and a TypeError from that iteration propagates, which is what produces
 * "TypeError: 'int' object is not iterable" for a scalar input.
 */
export function* flattenIter(iterable) {
  for (const item of pyIter(iterable)) {
    if (isIterable(item) && !isStrOrBytes(item)) {
      yield* flattenIter(item);
    } else {
      yield item;
    }
  }
}

/** flatten: list(flatten_iter(iterable)). */
export function flatten(iterable) {
  return new PyList([...flattenIter(iterable)]);
}

const UNSET = Symbol('unset');

/**
 * chunked_iter(src, size, fill=...): yields size-sized pieces of src. The final
 * piece is short unless a fill value is given. Pieces of a str/bytes source are
 * joined back into a str/bytes.
 */
export function* chunkedIter(src, size, fill = UNSET) {
  if (!isIterable(src)) throw new PyTypeError('expected an iterable');
  if (size <= 0n) throw new PyValueError('expected a positive integer chunk size');
  const isString = typeof src === 'string';
  const isBytes = src instanceof PyBytes;
  const iterator = pyIter(src)[Symbol.iterator]();
  const limit = Number(size);

  // boltons short-circuits on a falsy source, so an empty list yields nothing.
  if ((isString && src.length === 0) || (isBytes && src.data.length === 0)) return;

  for (;;) {
    const chunk = [];
    for (let i = 0; i < limit; i++) {
      const step = iterator.next();
      if (step.done) break;
      chunk.push(step.value);
    }
    if (chunk.length === 0) return;
    if (chunk.length < limit && fill !== UNSET) {
      while (chunk.length < limit) chunk.push(fill);
    }
    if (isString) yield chunk.join('');
    else if (isBytes) yield new PyBytes(chunk.map((b) => Number(b)));
    else yield new PyList(chunk);
  }
}

/** chunked(src, size, count=None, fill=...): the list form of chunked_iter. */
export function chunked(src, size, count = null, fill = UNSET) {
  const out = [];
  for (const chunk of chunkedIter(src, size, fill)) {
    if (count !== null && out.length >= count) break;
    out.push(chunk);
  }
  return new PyList(out);
}

