// Tokenizer for the Python expression handed to eval().
//
// Only expression syntax is needed: no statements, no indentation. Newlines are
// legal inside brackets and at the very end of the input, which is exactly what
// eval() accepts.

import { PySyntaxError } from '../errors.mjs';

const MAXLEVEL = 200; // CPython's tokenizer limit on nested brackets

const OPERATORS = [
  '**=', '//=', '>>=', '<<=', '...', '!=',
  '>>', '<<', '<=', '>=', '==', '**', '//', '->', ':=',
  '+=', '-=', '*=', '/=', '%=', '&=', '|=', '^=', '@=',
  '+', '-', '*', '/', '%', '@', '&', '|', '^', '~', '<', '>',
  '(', ')', '[', ']', '{', '}', ',', ':', '.', ';', '=',
];

const OPEN = { '(': ')', '[': ']', '{': '}' };
const CLOSE = { ')': '(', ']': '[', '}': '{' };

const isDigit = (ch) => ch >= '0' && ch <= '9';
const isHex = (ch) => isDigit(ch) || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');

// Python identifiers allow most Unicode letters; this covers the practical set.
const IDENT_START = /[A-Za-z_\p{L}\p{Nl}]/u;
const IDENT_CONT = /[A-Za-z0-9_\p{L}\p{Nl}\p{Mn}\p{Mc}\p{Nd}\p{Pc}]/u;

const STRING_PREFIXES = new Set([
  '', 'r', 'b', 'u', 'f', 'br', 'rb', 'fr', 'rf',
]);

export class Tokenizer {
  constructor(source) {
    this.src = source;
    this.pos = 0;
    this.line = 1;
    this.lineStart = 0;
    this.brackets = [];
    this.tokens = [];
  }

  get col() {
    return this.pos - this.lineStart; // 0-based
  }

  error(message, { pos = this.pos, endPos = null } = {}) {
    const line = this.lineOf(pos);
    return new PySyntaxError(message, {
      lineno: line,
      offset: pos - this.lineStartOf(line) + 1,
      endOffset: endPos === null ? null : endPos - this.lineStartOf(line) + 1,
      text: this.textOfLine(line),
    });
  }

  lineOf(pos) {
    let line = 1;
    for (let i = 0; i < pos && i < this.src.length; i++) {
      if (this.src[i] === '\n') line += 1;
    }
    return line;
  }

  lineStartOf(line) {
    let current = 1;
    for (let i = 0; i < this.src.length; i++) {
      if (current === line) return i;
      if (this.src[i] === '\n') current += 1;
    }
    return this.src.length;
  }

  textOfLine(line) {
    const start = this.lineStartOf(line);
    const end = this.src.indexOf('\n', start);
    return end === -1 ? this.src.slice(start) : this.src.slice(start, end + 1);
  }

  push(type, value, start, extra = {}) {
    this.tokens.push({
      type,
      value,
      start,
      end: this.pos,
      line: this.lineOf(start),
      ...extra,
    });
  }

  tokenize() {
    while (this.pos < this.src.length) {
      const ch = this.src[this.pos];
      if (ch === '\\' && this.src[this.pos + 1] === '\n') {
        this.pos += 2;
        this.line += 1;
        this.lineStart = this.pos;
        continue;
      }
      if (ch === '\n') {
        this.pos += 1;
        this.line += 1;
        this.lineStart = this.pos;
        if (this.brackets.length === 0) this.push('NEWLINE', '\n', this.pos - 1);
        continue;
      }
      if (ch === ' ' || ch === '\t' || ch === '\r' || ch === '\f' || ch === '\v') {
        this.pos += 1;
        continue;
      }
      if (ch === '#') {
        while (this.pos < this.src.length && this.src[this.pos] !== '\n') this.pos += 1;
        continue;
      }
      if (this.tryString()) continue;
      if (isDigit(ch) || (ch === '.' && isDigit(this.src[this.pos + 1]))) {
        this.readNumber();
        continue;
      }
      if (IDENT_START.test(ch)) {
        this.readName();
        continue;
      }
      this.readOperator();
    }
    if (this.brackets.length > 0) {
      const open = this.brackets[this.brackets.length - 1];
      throw this.error(`'${open.ch}' was never closed`, { pos: open.pos });
    }
    this.push('EOF', '', this.pos);
    return this.tokens;
  }

  readName() {
    const start = this.pos;
    while (this.pos < this.src.length && IDENT_CONT.test(this.src[this.pos])) this.pos += 1;
    const value = this.src.slice(start, this.pos);
    // A string prefix directly followed by a quote is part of the literal.
    const next = this.src[this.pos];
    if ((next === '"' || next === "'") && STRING_PREFIXES.has(value.toLowerCase())) {
      this.pos = start;
      this.tryString();
      return;
    }
    this.push('NAME', value, start);
  }

  tryString() {
    const start = this.pos;
    let i = this.pos;
    let prefix = '';
    while (i < this.src.length && /[A-Za-z]/.test(this.src[i]) && prefix.length < 2) {
      prefix += this.src[i];
      i += 1;
    }
    const quote = this.src[i];
    if (quote !== '"' && quote !== "'") return false;
    if (!STRING_PREFIXES.has(prefix.toLowerCase())) return false;

    this.pos = i;
    const triple = this.src.startsWith(quote.repeat(3), this.pos);
    const delimiter = triple ? quote.repeat(3) : quote;
    this.pos += delimiter.length;
    const bodyStart = this.pos;
    const raw = prefix.toLowerCase().includes('r');

    for (;;) {
      if (this.pos >= this.src.length) {
        const kind = triple ? 'unterminated triple-quoted string literal' : 'unterminated string literal';
        throw this.error(`${kind} (detected at line ${this.lineOf(this.pos)})`, { pos: start });
      }
