// Recursive-descent parser for Python expressions, producing a small AST.
//
// Precedence follows the Python reference grammar. Only expression forms are
// accepted, which is exactly what eval() compiles.

import { PySyntaxError } from '../errors.mjs';
import { tokenize } from './lexer.mjs';

const KEYWORDS = new Set([
  'and', 'or', 'not', 'in', 'is', 'if', 'else', 'for', 'lambda', 'None', 'True', 'False',
  'await', 'yield',
]);

const COMPARISONS = new Set(['<', '>', '==', '>=', '<=', '!=']);

class Parser {
  constructor(source) {
    this.source = source;
    this.tokens = tokenize(source).filter((t) => t.type !== 'NEWLINE' || false);
    // Newlines only matter as "end of expression"; drop them but remember that
    // anything after the first one must be blank.
    this.tokens = this.tokens.filter((t) => t.type !== 'NEWLINE');
    this.index = 0;
  }

  get current() {
    return this.tokens[this.index];
  }

  at(type, value = null) {
    const token = this.current;
    if (token.type !== type) return false;
    return value === null || token.value === value;
  }

  atOp(...values) {
    return this.current.type === 'OP' && values.includes(this.current.value);
  }

  atName(...values) {
    return this.current.type === 'NAME' && values.includes(this.current.value);
  }

  next() {
    return this.tokens[this.index++];
  }

  expectOp(value) {
    if (!this.atOp(value)) throw this.syntaxError();
    return this.next();
  }

  syntaxError(message = 'invalid syntax', token = this.current) {
    const src = this.source;
    let lineStart = 0;
    let lineno = 1;
    for (let i = 0; i < token.start && i < src.length; i++) {
      if (src[i] === '\n') {
        lineno += 1;
        lineStart = i + 1;
      }
    }
    const lineEnd = src.indexOf('\n', lineStart);
    const text = lineEnd === -1 ? src.slice(lineStart) : src.slice(lineStart, lineEnd + 1);
    const atEnd = token.type === 'EOF';
    return new PySyntaxError(message, {
      lineno,
      // CPython reports no usable column for an error at end of input, and the
      // traceback then prints no caret line.
      offset: atEnd ? 0 : token.start - lineStart + 1,
      endOffset: atEnd ? 0 : token.end - lineStart + 1,
      text,
    });
  }

  parse() {
    if (this.tokens.length === 1) {
      // Nothing but EOF: eval('') reports line 0 with empty text.
      throw new PySyntaxError('invalid syntax', { lineno: 0, offset: 0, text: '' });
    }
    const node = this.parseTestListStar();
    if (!this.at('EOF')) throw this.syntaxError();
    return node;
  }

  /** `1, 2` at the top level (or in a subscript) builds a tuple. */
  parseTestListStar() {
    const first = this.parseStarOrTest();
    if (!this.atOp(',')) return first;
    const elts = [first];
    while (this.atOp(',')) {
      this.next();
      if (this.at('EOF') || this.atOp(')', ']', '}', ':', '=')) break;
      elts.push(this.parseStarOrTest());
    }
    return { kind: 'Tuple', elts };
  }

  parseStarOrTest() {
    if (this.atOp('*')) {
      this.next();
      return { kind: 'Starred', value: this.parseOr() };
    }
    return this.parseTest();
  }

  parseTest() {
    if (this.atName('lambda')) return this.parseLambda();
    const value = this.parseOr();
    if (this.atName('if')) {
      this.next();
      const test = this.parseOr();
      if (!this.atName('else')) throw this.syntaxError('expected \'else\' after \'if\' expression');
      this.next();
      const orelse = this.parseTest();
      return { kind: 'IfExp', test, body: value, orelse };
    }
    return value;
  }

  parseLambda() {
    this.next(); // lambda
    const params = [];
    while (!this.atOp(':')) {
      if (this.atOp('*') || this.atOp('**')) {
        const star = this.next().value;
        const name = this.at('NAME') ? this.next().value : null;
        params.push({ name, kind: star === '*' ? 'vararg' : 'kwarg' });
      } else if (this.at('NAME')) {
        const name = this.next().value;
        let dflt = null;
        if (this.atOp('=')) {
          this.next();
          dflt = this.parseTest();
        }
        params.push({ name, kind: 'positional', default: dflt });
      } else {
        throw this.syntaxError();
      }
      if (this.atOp(',')) this.next();
      else break;
    }
    this.expectOp(':');
    const body = this.parseTest();
    return { kind: 'Lambda', params, body };
  }

  parseOr() {
    let left = this.parseAnd();
    while (this.atName('or')) {
      this.next();
      const right = this.parseAnd();
      if (left.kind === 'BoolOp' && left.op === 'or') left.values.push(right);
      else left = { kind: 'BoolOp', op: 'or', values: [left, right] };
    }
    return left;
  }

  parseAnd() {
    let left = this.parseNot();
    while (this.atName('and')) {
      this.next();
      const right = this.parseNot();
      if (left.kind === 'BoolOp' && left.op === 'and') left.values.push(right);
      else left = { kind: 'BoolOp', op: 'and', values: [left, right] };
    }
    return left;
  }

  parseNot() {
    if (this.atName('not')) {
      this.next();
      return { kind: 'UnaryOp', op: 'not', operand: this.parseNot() };
    }
    return this.parseComparison();
  }

  parseComparison() {
    const left = this.parseBitOr();
    const ops = [];
    const comparators = [];
    for (;;) {
      let op = null;
      if (this.current.type === 'OP' && COMPARISONS.has(this.current.value)) {
        op = this.next().value;
      } else if (this.atName('in')) {
        this.next();
        op = 'in';
      } else if (this.atName('not') && this.tokens[this.index + 1]?.value === 'in') {
        this.next();
        this.next();
        op = 'not in';
      } else if (this.atName('is')) {
        this.next();
        if (this.atName('not')) {
          this.next();
          op = 'is not';
        } else {
          op = 'is';
        }
      }
      if (op === null) break;
      ops.push(op);
      comparators.push(this.parseBitOr());
    }
    if (ops.length === 0) return left;
    return { kind: 'Compare', left, ops, comparators };
  }

  binaryLevel(nextLevel, operators) {
    let left = nextLevel.call(this);
    while (this.current.type === 'OP' && operators.includes(this.current.value)) {
      const op = this.next().value;
      const right = nextLevel.call(this);
      left = { kind: 'BinOp', op, left, right };
    }
    return left;
  }

  parseBitOr() {
    return this.binaryLevel(this.parseBitXor, ['|']);
  }

  parseBitXor() {
    return this.binaryLevel(this.parseBitAnd, ['^']);
  }

  parseBitAnd() {
    return this.binaryLevel(this.parseShift, ['&']);
  }

  parseShift() {
    return this.binaryLevel(this.parseArith, ['<<', '>>']);
  }

  parseArith() {
    return this.binaryLevel(this.parseTerm, ['+', '-']);
  }

  parseTerm() {
    return this.binaryLevel(this.parseFactor, ['*', '/', '//', '%', '@']);
  }

  parseFactor() {
    if (this.atOp('+', '-', '~')) {
      const op = this.next().value;
      return { kind: 'UnaryOp', op, operand: this.parseFactor() };
    }
    return this.parsePower();
  }

  parsePower() {
    const base = this.parseUnaryPostfix();
    if (this.atOp('**')) {
      this.next();
      const exponent = this.parseFactor();
      return { kind: 'BinOp', op: '**', left: base, right: exponent };
    }
    return base;
  }

  parseUnaryPostfix() {
    let node = this.parseAtom();
    for (;;) {
      if (this.atOp('(')) {
        node = this.parseCall(node);
      } else if (this.atOp('[')) {
        node = this.parseSubscript(node);
      } else if (this.atOp('.')) {
        this.next();
        if (!this.at('NAME')) throw this.syntaxError('invalid syntax');
        node = { kind: 'Attribute', value: node, attr: this.next().value };
      } else {
        return node;
      }
    }
  }

  parseCall(func) {
    this.expectOp('(');
    const args = [];
    const keywords = [];
    while (!this.atOp(')')) {
      if (this.atOp('*')) {
        this.next();
        args.push({ kind: 'Starred', value: this.parseTest() });
      } else if (this.atOp('**')) {
        this.next();
        keywords.push({ arg: null, value: this.parseTest() });
      } else if (this.at('NAME') && this.tokens[this.index + 1]?.value === '=' && this.tokens[this.index + 1]?.type === 'OP' && !KEYWORDS.has(this.current.value)) {
        const arg = this.next().value;
        this.next(); // '='
        keywords.push({ arg, value: this.parseTest() });
      } else {
        let value = this.parseTest();
        if (this.atName('for')) {
          value = { kind: 'Comp', type: 'gen', elt: value, generators: this.parseComprehensionClauses() };
        }
        args.push(value);
      }
      if (this.atOp(',')) this.next();
      else break;
    }
    this.expectOp(')');
    return { kind: 'Call', func, args, keywords };
  }

  parseSubscript(value) {
    this.expectOp('[');
    const parts = [];
    let sawComma = false;
    for (;;) {
      parts.push(this.parseSubscriptItem());
      if (this.atOp(',')) {
        sawComma = true;
        this.next();
        if (this.atOp(']')) break;
        continue;
      }
      break;
    }
    this.expectOp(']');
    const slice = sawComma ? { kind: 'Tuple', elts: parts } : parts[0];
    return { kind: 'Subscript', value, slice };
  }

  parseSubscriptItem() {
    let lower = null;
    if (!this.atOp(':')) {
      if (this.atOp(']')) throw this.syntaxError();
      lower = this.parseStarOrTest();
      if (!this.atOp(':')) return lower;
    }
    this.expectOp(':');
    let upper = null;
    if (!this.atOp(':', ']', ',')) upper = this.parseTest();
    let step = null;
    if (this.atOp(':')) {
      this.next();
      if (!this.atOp(']', ',')) step = this.parseTest();
    }
    return { kind: 'Slice', lower, upper, step };
  }

  parseComprehensionClauses() {
    const generators = [];
    while (this.atName('for')) {
      this.next();
      const target = this.parseTarget();
      if (!this.atName('in')) throw this.syntaxError();
      this.next();
      const iter = this.parseOrNoCond();
      const ifs = [];
      while (this.atName('if')) {
        this.next();
        ifs.push(this.parseOrNoCond());
      }
      generators.push({ target, iter, ifs });
    }
    return generators;
  }

  /** The iterable of a comprehension binds tighter than a conditional. */
  parseOrNoCond() {
    return this.parseOr();
  }

  parseTarget() {
    const parseOne = () => {
      if (this.atOp('(') || this.atOp('[')) {
        const closer = this.next().value === '(' ? ')' : ']';
        const elts = [];
        while (!this.atOp(closer)) {
          elts.push(parseOne());
          if (this.atOp(',')) this.next();
          else break;
        }
        this.expectOp(closer);
        return { kind: 'TargetTuple', elts };
      }
      if (this.atOp('*')) {
        this.next();
        return { kind: 'TargetStar', value: parseOne() };
      }
      if (!this.at('NAME') || KEYWORDS.has(this.current.value)) throw this.syntaxError();
      return { kind: 'TargetName', id: this.next().value };
    };
    const first = parseOne();
    if (!this.atOp(',')) return first;
    const elts = [first];
    while (this.atOp(',')) {
      this.next();
      if (this.atName('in')) break;
      elts.push(parseOne());
    }
    return { kind: 'TargetTuple', elts };
  }

  parseAtom() {
    const token = this.current;
    if (token.type === 'NUMBER') {
      this.next();
      return { kind: 'Num', value: token.value, numKind: token.kind };
    }
    if (token.type === 'STRING') return this.parseStringGroup();
    if (token.type === 'NAME') {
      if (token.value === 'None') {
        this.next();
        return { kind: 'Const', value: null };
      }
      if (token.value === 'True' || token.value === 'False') {
        this.next();
        return { kind: 'Const', value: token.value === 'True' };
      }
      if (token.value === 'lambda') return this.parseLambda();
      if (token.value === 'not') return this.parseNot();
      if (KEYWORDS.has(token.value)) throw this.syntaxError();
      this.next();
      return { kind: 'Name', id: token.value };
    }
    if (token.type === 'OP') {
      if (token.value === '...') {
        this.next();
        return { kind: 'Ellipsis' };
      }
      if (token.value === '(') return this.parseParen();
      if (token.value === '[') return this.parseListDisplay();
      if (token.value === '{') return this.parseBraceDisplay();
    }
    throw this.syntaxError();
  }

  parseStringGroup() {
    const parts = [];
    while (this.at('STRING')) parts.push(this.next());
    return { kind: 'StringGroup', parts };
  }

  parseParen() {
    this.expectOp('(');
    if (this.atOp(')')) {
      this.next();
      return { kind: 'Tuple', elts: [] };
    }
    const first = this.parseStarOrTest();
    if (this.atName('for')) {
      const generators = this.parseComprehensionClauses();
      this.expectOp(')');
      return { kind: 'Comp', type: 'gen', elt: first, generators };
    }
    if (this.atOp(',')) {
      const elts = [first];
      while (this.atOp(',')) {
        this.next();
        if (this.atOp(')')) break;
        elts.push(this.parseStarOrTest());
      }
      this.expectOp(')');
      return { kind: 'Tuple', elts };
    }
    this.expectOp(')');
    return { kind: 'Paren', value: first };
  }

  parseListDisplay() {
    this.expectOp('[');
    if (this.atOp(']')) {
      this.next();
      return { kind: 'List', elts: [] };
    }
    const first = this.parseStarOrTest();
    if (this.atName('for')) {
      const generators = this.parseComprehensionClauses();
      this.expectOp(']');
      return { kind: 'Comp', type: 'list', elt: first, generators };
    }
    const elts = [first];
    while (this.atOp(',')) {
      this.next();
      if (this.atOp(']')) break;
      elts.push(this.parseStarOrTest());
    }
    this.expectOp(']');
    return { kind: 'List', elts };
  }

  parseBraceDisplay() {
    this.expectOp('{');
    if (this.atOp('}')) {
      this.next();
      return { kind: 'Dict', keys: [], values: [] };
    }
    if (this.atOp('**')) {
      const keys = [];
      const values = [];
      while (!this.atOp('}')) {
        if (this.atOp('**')) {
          this.next();
          keys.push(null);
          values.push(this.parseOr());
        } else {
          const key = this.parseTest();
          this.expectOp(':');
          keys.push(key);
          values.push(this.parseTest());
        }
        if (this.atOp(',')) this.next();
        else break;
      }
      this.expectOp('}');
      return { kind: 'Dict', keys, values };
    }
    const first = this.parseStarOrTest();
    if (this.atOp(':')) {
      this.next();
      const firstValue = this.parseTest();
      if (this.atName('for')) {
        const generators = this.parseComprehensionClauses();
        this.expectOp('}');
        return { kind: 'Comp', type: 'dict', key: first, value: firstValue, generators };
      }
      const keys = [first];
      const values = [firstValue];
      while (this.atOp(',')) {
        this.next();
        if (this.atOp('}')) break;
        if (this.atOp('**')) {
          this.next();
          keys.push(null);
          values.push(this.parseOr());
          continue;
        }
        keys.push(this.parseTest());
        this.expectOp(':');
        values.push(this.parseTest());
      }
      this.expectOp('}');
      return { kind: 'Dict', keys, values };
    }
    if (this.atName('for')) {
      const generators = this.parseComprehensionClauses();
      this.expectOp('}');
      return { kind: 'Comp', type: 'set', elt: first, generators };
    }
    const elts = [first];
    while (this.atOp(',')) {
      this.next();
      if (this.atOp('}')) break;
      elts.push(this.parseStarOrTest());
    }
    this.expectOp('}');
    return { kind: 'Set', elts };
  }
}

export function parse(source) {
  return new Parser(source).parse();
}

