// Decoding of string / bytes literals and f-strings.

import { PySyntaxError, UnsupportedError } from '../errors.mjs';
import { PyBytes } from '../types.mjs';

const SIMPLE_ESCAPES = {
  '\\': '\\',
  "'": "'",
  '"': '"',
  a: '\x07',
  b: '\x08',
  f: '\x0c',
  n: '\n',
  r: '\r',
  t: '\t',
  v: '\x0b',
};

const OCTAL = new Set(['0', '1', '2', '3', '4', '5', '6', '7']);
const isHexDigit = (ch) => ch !== undefined && /[0-9a-fA-F]/.test(ch);

/**
 * Decode the escape sequences in a string literal body.
 *
 * `warn` is called with the offending escape text for every invalid escape,
 * which is how CPython's SyntaxWarning ("invalid escape sequence '\\d'") is
 * reproduced.
 */
export function decodeStringBody(body, { raw = false, bytes = false, warn = null } = {}) {
  if (raw) {
    if (bytes) checkAscii(body);
    return body;
  }
  let out = '';
  let i = 0;
  while (i < body.length) {
    const ch = body[i];
    if (ch !== '\\') {
      out += ch;
      i += 1;
      continue;
    }
    const next = body[i + 1];
    if (next === undefined) {
      out += '\\';
      i += 1;
      continue;
    }
    if (next === '\n') {
      i += 2;
      continue;
    }
    if (next in SIMPLE_ESCAPES) {
      out += SIMPLE_ESCAPES[next];
      i += 2;
      continue;
    }
    if (OCTAL.has(next)) {
      let digits = '';
      let j = i + 1;
      while (digits.length < 3 && OCTAL.has(body[j])) {
        digits += body[j];
        j += 1;
      }
      out += String.fromCharCode(parseInt(digits, 8));
      i = j;
      continue;
    }
    if (next === 'x') {
      const hex = body.slice(i + 2, i + 4);
      if (hex.length < 2 || !isHexDigit(hex[0]) || !isHexDigit(hex[1])) {
        throw new PySyntaxError(
          `(unicode error) '${bytes ? 'unicodeescape' : 'unicodeescape'}' codec can't decode bytes in position ${i}-${i + 1}: truncated \\xXX escape`,
        );
      }
