}

/**
 * Split an f-string body into literal chunks and {expression} placeholders.
 * Returns [{ type: 'text', value }, { type: 'expr', source, conversion, spec }].
 * `spec` is itself a list of chunks so nested replacements work.
 */
export function parseFString(body) {
  const chunks = [];
