      if (c === ':' && depth === 0) {
        i += 1;
        let specText = '';
        let specDepth = 0;
        while (i < body.length) {
          const s = body[i];
          if (s === '{') specDepth += 1;
          if (s === '}') {
            if (specDepth === 0) break;
            specDepth -= 1;
          }
