// Decoding of string / bytes literals and f-strings.

import { PySyntaxError, UnsupportedError } from '../errors.mjs';
import { PyBytes } from '../types.mjs';

const SIMPLE_ESCAPES = {
  '\\': '\\',
  "'": "'",
  '"': '"',
  a: '\x07',
  b: '\x08',
  f: '\x0c',
  n: '\n',
  r: '\r',
  t: '\t',
  v: '\x0b',
};

const OCTAL = new Set(['0', '1', '2', '3', '4', '5', '6', '7']);
const isHexDigit = (ch) => ch !== undefined && /[0-9a-fA-F]/.test(ch);

/**
 * Decode the escape sequences in a string literal body.
