 * `warn` is called with the offending escape text for every invalid escape,
 * which is how CPython's SyntaxWarning ("invalid escape sequence '\\d'") is
 * reproduced.
 */
export function decodeStringBody(body, { raw = false, bytes = false, warn = null } = {}) {
  if (raw) {
    if (bytes) checkAscii(body);
    return body;
  }
  let out = '';
  let i = 0;
  while (i < body.length) {
    const ch = body[i];
    if (ch !== '\\') {
      out += ch;
      i += 1;
      continue;
    }
    const next = body[i + 1];
    if (next === undefined) {
      out += '\\';
      i += 1;
      continue;
    }
    if (next === '\n') {
      i += 2;
      continue;
    }
    if (next in SIMPLE_ESCAPES) {
      out += SIMPLE_ESCAPES[next];
      i += 2;
      continue;
    }
    if (OCTAL.has(next)) {
      let digits = '';
      let j = i + 1;
