// The evaluator: walks the AST produced by parser.mjs.

import {
  PyAttributeError,
  PyIndexError,
  PyKeyError,
  PyNameError,
  PySyntaxError,
  PyTypeError,
  PyValueError,
  notCallable,
} from '../errors.mjs';
import {
  ELLIPSIS,
  PyBuiltin,
  PyByteArray,
  PyBytes,
  PyComplex,
  PyDict,
  PyDictView,
  PyFunction,
  PyIterator,
  PyList,
  PyMemoryView,
  PyModule,
  PyNamespace,
  PyObjectLike,
  PyRange,
  PySet,
  PySlice,
  PyTuple,
  PyType,
  asIndexable,
  chars,
  isIterable,
  pyEq,
  pyIter,
  strLen,
  truthy,
  typeName,
} from '../types.mjs';
import { asInt, isInt } from '../numeric.mjs';
import { binaryOp, compareOp, unaryOp } from '../operators.mjs';
import { pyRepr, pyStr } from '../repr.mjs';
import { constantSetDisplayOrder, setElementOrder } from '../setimpl.mjs';
import { formatValue } from '../strformat.mjs';
import { bytesFromLatin1, decodeStringBody, parseFString } from './strings.mjs';
import { getAttribute } from './attributes.mjs';

class Scope {
  constructor(parent = null) {
    this.vars = new Map();
    this.parent = parent;
  }

  lookup(name) {
    let scope = this;
    while (scope !== null) {
      if (scope.vars.has(name)) return { found: true, value: scope.vars.get(name) };
      scope = scope.parent;
    }
    return { found: false };
  }

  define(name, value) {
    this.vars.set(name, value);
  }
}

export class Interpreter {
  /**
   * @param {Map<string, any>} globals  eval()'s globals (the script's module namespace)
   * @param {Map<string, any>} builtins the builtin namespace
   * @param {(text: string, line: number) => void} warn  SyntaxWarning sink
   */
  constructor(globals, builtins, warn = null) {
    this.globals = globals;
    this.builtins = builtins;
    this.warn = warn;
    this.frames = [];
  }

  run(node) {
    return this.evaluate(node, new Scope());
  }

  /** Track a synthetic frame so tracebacks can mention <lambda>/<genexpr>. */
  inFrame(name, fn) {
    this.frames.push(name);
    try {
      return fn();
    } catch (err) {
      if (err && Array.isArray(err.pyFrames) && !err.pyFramesSealed) {
        err.pyFrames.unshift({ file: '<string>', line: 1, name });
      }
      throw err;
    } finally {
      this.frames.pop();
    }
  }

  evaluate(node, scope) {
    switch (node.kind) {
      case 'Const':
        return node.value;
      case 'Num':
        if (node.numKind === 'imag') return new PyComplex(0, node.value);
        return node.value;
      case 'Ellipsis':
        return ELLIPSIS;
      case 'Paren':
        return this.evaluate(node.value, scope);
      case 'Name':
        return this.loadName(node.id, scope);
      case 'StringGroup':
        return this.evalStringGroup(node, scope);
      case 'List':
        return new PyList(this.evalElements(node.elts, scope));
      case 'Tuple':
        return new PyTuple(this.evalElements(node.elts, scope));
      case 'Set': {
        const values = this.evalElements(node.elts, scope);
        const order = node.allConstant ? constantSetDisplayOrder(values) : setElementOrder(values);
        return new PySet(order, false);
      }
      case 'Dict':
        return this.evalDict(node, scope);
      case 'BinOp':
        return binaryOp(node.op, this.evaluate(node.left, scope), this.evaluate(node.right, scope));
      case 'UnaryOp':
        return unaryOp(node.op, this.evaluate(node.operand, scope));
      case 'BoolOp': {
        let value;
        for (const item of node.values) {
          value = this.evaluate(item, scope);
          const t = truthy(value);
          if (node.op === 'and' ? !t : t) return value;
        }
        return value;
      }
      case 'Compare': {
        let left = this.evaluate(node.left, scope);
        for (let i = 0; i < node.ops.length; i++) {
          const right = this.evaluate(node.comparators[i], scope);
          if (!truthy(compareOp(node.ops[i], left, right))) return false;
          left = right;
        }
        return true;
      }
      case 'IfExp':
        return truthy(this.evaluate(node.test, scope))
          ? this.evaluate(node.body, scope)
          : this.evaluate(node.orelse, scope);
      case 'Lambda':
        return new PyFunction('<lambda>', node.params, node.body, scope);
      case 'Call':
        return this.evalCall(node, scope);
      case 'Subscript':
        return this.getItem(this.evaluate(node.value, scope), this.evalSlice(node.slice, scope));
      case 'Attribute':
        return this.getAttr(this.evaluate(node.value, scope), node.attr);
      case 'Comp':
        return this.evalComprehension(node, scope);
      case 'Starred':
        throw new PySyntaxError("can't use starred expression here");
      case 'JoinedStr':
        return this.evalJoinedStr(node.chunks, scope);
      default:
        throw new PySyntaxError('invalid syntax');
    }
  }

  loadName(name, scope) {
    const local = scope.lookup(name);
    if (local.found) return local.value;
    if (this.globals.has(name)) return this.globals.get(name);
    if (this.builtins.has(name)) return this.builtins.get(name);
    throw new PyNameError(`name '${name}' is not defined`);
  }

  evalElements(elements, scope) {
    const out = [];
    for (const element of elements) {
      if (element.kind === 'Starred') {
        const value = this.evaluate(element.value, scope);
        if (!isIterable(value)) {
          throw new PyTypeError(`Value after * must be an iterable, not ${typeName(value)}`);
        }
        out.push(...pyIter(value));
      } else {
        out.push(this.evaluate(element, scope));
      }
    }
    return out;
  }

  evalDict(node, scope) {
    const dict = new PyDict([]);
    for (let i = 0; i < node.keys.length; i++) {
      if (node.keys[i] === null) {
        const source = this.evaluate(node.values[i], scope);
        if (!(source instanceof PyDict)) {
          throw new PyTypeError(`'${typeName(source)}' object is not a mapping`);
        }
        for (const entry of source.entries) this.setDictItem(dict, entry.key, entry.value);
        continue;
      }
      const key = this.evaluate(node.keys[i], scope);
      const value = this.evaluate(node.values[i], scope);
      this.setDictItem(dict, key, value);
    }
    return dict;
  }

  setDictItem(dict, key, value) {
    const existing = dict.entries.find((entry) => pyEq(entry.key, key));
    if (existing !== undefined) existing.value = value;
    else dict.entries.push({ key, value });
  }

  evalStringGroup(node, scope) {
    const isBytes = node.parts.some((part) => part.prefix.includes('b'));
    const mixed = node.parts.some((part) => !part.prefix.includes('b'));
    if (isBytes && mixed) {
      throw new PySyntaxError('cannot mix bytes and nonbytes literals');
    }
    if (isBytes) {
      let text = '';
      for (const part of node.parts) {
        text += decodeStringBody(part.value, {
          raw: part.raw,
          bytes: true,
          warn: (escape) => this.emitEscapeWarning(escape, part),
        });
      }
      return bytesFromLatin1(text);
    }
    const chunks = [];
    for (const part of node.parts) {
      if (part.prefix.includes('f')) {
        for (const chunk of parseFString(part.value)) {
          if (chunk.type === 'text') {
            chunks.push({
              type: 'text',
              value: decodeStringBody(chunk.value, {
                raw: part.raw,
                warn: (escape) => this.emitEscapeWarning(escape, part),
              }),
            });
          } else {
            chunks.push(chunk);
          }
        }
      } else {
        chunks.push({
          type: 'text',
          value: decodeStringBody(part.value, {
            raw: part.raw,
            warn: (escape) => this.emitEscapeWarning(escape, part),
          }),
        });
      }
    }
    if (chunks.every((chunk) => chunk.type === 'text')) {
      return chunks.map((chunk) => chunk.value).join('');
    }
    return this.evalJoinedStr(chunks, scope);
  }

  emitEscapeWarning(escape, part) {
    if (this.warn !== null) this.warn(`invalid escape sequence '${escape}'`, part.line ?? 1);
  }

  evalJoinedStr(chunks, scope) {
    let out = '';
    for (const chunk of chunks) {
      if (chunk.type === 'text') {
        out += chunk.value;
        continue;
      }
      const { parse } = requireParser();
      const ast = parse(chunk.source);
      const value = this.evaluate(ast, scope);
      let text;
      if (chunk.conversion === 'r') text = pyRepr(value);
      else if (chunk.conversion === 'a') text = pyRepr(value);
      else if (chunk.conversion === 's') text = pyStr(value);
      else text = null;
      const spec = chunk.spec === null ? '' : this.evalJoinedStr(chunk.spec, scope);
      if (chunk.selfDocumenting) out += `${chunk.source}=`;
      if (text !== null) out += spec === '' ? text : formatValue(text, spec);
      else out += formatValue(value, spec);
    }
    return out;
  }

  evalCall(node, scope) {
    const func = this.evaluate(node.func, scope);
    const args = [];
    for (const arg of node.args) {
      if (arg.kind === 'Starred') {
        const value = this.evaluate(arg.value, scope);
        args.push(...pyIter(value));
      } else {
        args.push(this.evaluate(arg, scope));
      }
    }
    const kwargs = new Map();
    for (const keyword of node.keywords) {
      if (keyword.arg === null) {
        const mapping = this.evaluate(keyword.value, scope);
        if (!(mapping instanceof PyDict)) {
          throw new PyTypeError(
            `argument after ** must be a mapping, not ${typeName(mapping)}`,
          );
        }
        for (const entry of mapping.entries) kwargs.set(pyStr(entry.key), entry.value);
      } else {
        kwargs.set(keyword.arg, this.evaluate(keyword.value, scope));
      }
    }
    return this.call(func, args, kwargs);
  }

  call(func, args, kwargs = new Map()) {
    if (func instanceof PyBuiltin || func instanceof PyType) {
      return func.call(args, kwargs, this);
    }
    if (func instanceof PyFunction) {
      const scope = new Scope(func.env);
      const positional = func.params.filter((p) => p.kind === 'positional');
      positional.forEach((param, i) => {
        if (i < args.length) scope.define(param.name, args[i]);
        else if (kwargs.has(param.name)) scope.define(param.name, kwargs.get(param.name));
        else if (param.default !== null && param.default !== undefined) {
          scope.define(param.name, this.evaluate(param.default, func.env));
        } else {
          throw new PyTypeError(
            `${func.name}() missing 1 required positional argument: '${param.name}'`,
          );
        }
      });
      const vararg = func.params.find((p) => p.kind === 'vararg');
      if (vararg && vararg.name) {
        scope.define(vararg.name, new PyTuple(args.slice(positional.length)));
      } else if (args.length > positional.length) {
        throw new PyTypeError(
          `${func.name}() takes ${positional.length} positional argument${positional.length === 1 ? '' : 's'} but ${args.length} were given`,
        );
      }
      const kwarg = func.params.find((p) => p.kind === 'kwarg');
      if (kwarg && kwarg.name) {
        const rest = new PyDict([]);
        for (const [key, value] of kwargs) {
          if (!positional.some((p) => p.name === key)) rest.entries.push({ key, value });
        }
        scope.define(kwarg.name, rest);
      }
      return this.inFrame('<lambda>', () => this.evaluate(func.body, scope));
    }
    throw notCallable(typeName(func));
  }

  evalSlice(node, scope) {
    if (node.kind === 'Slice') {
      return new PySlice(
        node.lower === null ? null : this.evaluate(node.lower, scope),
        node.upper === null ? null : this.evaluate(node.upper, scope),
        node.step === null ? null : this.evaluate(node.step, scope),
      );
    }
    return this.evaluate(node, scope);
  }

  getItem(container, index) {
    if (index instanceof PySlice) return sliceValue(container, index);
    if (container instanceof PyDict) {
      const entry = container.entries.find((e) => pyEq(e.key, index));
      if (entry === undefined) throw new PyKeyError(pyRepr(index));
      return entry.value;
    }
    if (typeof container === 'string') {
      const items = chars(container);
      return items[normalizeIndex(index, items.length, 'string')];
    }
    if (container instanceof PyBytes) {
      const i = normalizeIndex(index, container.data.length, typeName(container));
      return BigInt(container.data[i]);
    }
    if (container instanceof PyList || container instanceof PyTuple) {
      const kind = container instanceof PyList ? 'list' : 'tuple';
      if (!isInt(index)) {
        throw new PyTypeError(`${kind} indices must be integers or slices, not ${typeName(index)}`);
      }
      return container.items[normalizeIndex(index, container.items.length, kind)];
    }
    if (container instanceof PyRange) {
      const length = Number(container.length);
      const i = normalizeIndex(index, length, 'range');
      return container.at(BigInt(i));
    }
    throw new PyTypeError(`'${typeName(container)}' object is not subscriptable`);
  }

  getAttr(value, name) {
    return getAttribute(this, value, name);
  }

  evalComprehension(node, scope) {
    if (node.type === 'gen') {
      const outerIter = pyIter(this.evaluate(node.generators[0].iter, scope));
      const self = this;
      const generator = (function* run() {
        yield* self.iterateComprehension(node, scope, 0, outerIter, (innerScope) =>
          [self.evaluate(node.elt, innerScope)],
        );
      })();
      return new PyIterator(generator, 'generator');
    }
    const results = [];
    const outerIter = pyIter(this.evaluate(node.generators[0].iter, scope));
    if (node.type === 'dict') {
      const dict = new PyDict([]);
      for (const _ of this.iterateComprehension(node, scope, 0, outerIter, (innerScope) => {
        const key = this.evaluate(node.key, innerScope);
        const value = this.evaluate(node.value, innerScope);
        this.setDictItem(dict, key, value);
        return [null];
      })) {
        void _;
      }
      return dict;
    }
    for (const value of this.iterateComprehension(node, scope, 0, outerIter, (innerScope) => [
      this.evaluate(node.elt, innerScope),
    ])) {
      results.push(value);
    }
    if (node.type === 'set') return new PySet(setElementOrder(results), false);
    return new PyList(results);
  }

  *iterateComprehension(node, scope, level, iterable, emit) {
    const clause = node.generators[level];
    const source = iterable ?? pyIter(this.evaluate(clause.iter, scope));
    for (const item of source) {
      const inner = new Scope(scope);
      this.assignTarget(clause.target, item, inner);
      let skip = false;
      for (const condition of clause.ifs) {
        if (!truthy(this.evaluate(condition, inner))) {
          skip = true;
          break;
        }
      }
      if (skip) continue;
      if (level + 1 < node.generators.length) {
        yield* this.iterateComprehension(node, inner, level + 1, null, emit);
      } else {
        yield* emit(inner);
      }
    }
  }

  assignTarget(target, value, scope) {
    if (target.kind === 'TargetName') {
      scope.define(target.id, value);
      return;
    }
    if (target.kind === 'TargetTuple') {
      if (!isIterable(value)) {
        throw new PyTypeError(`cannot unpack non-iterable ${typeName(value)} object`);
      }
      const items = Array.from(pyIter(value));
      const starIndex = target.elts.findIndex((element) => element.kind === 'TargetStar');
      if (starIndex === -1) {
        if (items.length < target.elts.length) {
          throw new PyValueError(
            `not enough values to unpack (expected ${target.elts.length}, got ${items.length})`,
          );
        }
        if (items.length > target.elts.length) {
          throw new PyValueError(`too many values to unpack (expected ${target.elts.length})`);
        }
        target.elts.forEach((element, i) => this.assignTarget(element, items[i], scope));
        return;
      }
      const before = target.elts.slice(0, starIndex);
      const after = target.elts.slice(starIndex + 1);
      before.forEach((element, i) => this.assignTarget(element, items[i], scope));
      const restCount = items.length - before.length - after.length;
      this.assignTarget(
        target.elts[starIndex].value,
        new PyList(items.slice(before.length, before.length + restCount)),
        scope,
      );
      after.forEach((element, i) =>
        this.assignTarget(element, items[before.length + restCount + i], scope),
      );
      return;
    }
    throw new PySyntaxError('cannot assign to expression');
  }
}

function normalizeIndex(index, length, kindName) {
  if (index instanceof PySlice) throw new PyTypeError('slice used as index');
