    if (name === 'denominator') return 1n;
    const bound = bindTable(INT_METHODS, asInt(value), name, interp);
    if (bound) return bound;
  } else if (typeof value === 'number') {
    if (name === 'real') return value;
    if (name === 'imag') return 0;
