        }
      })(),
      'map',
    );
  });
  define('filter', (args, kwargs, interp) => {
    const [func, iterable] = args;
    const items = pyIter(iterable);
    return new PyIterator(
      (function* run() {
        for (const item of items) {
          const keep = func === null ? truthy(item) : truthy(interp.call(func, [item]));
          if (keep) yield item;
        }
      })(),
      'filter',
    );
  });
  define('any', (args) => {
    for (const item of pyIter(args[0])) if (truthy(item)) return true;
    return false;
  });
  define('all', (args) => {
    for (const item of pyIter(args[0])) if (!truthy(item)) return false;
    return true;
  });
  define('chr', (args) => {
    const code = Number(argInt(args[0]));
    if (code < 0 || code > 0x10ffff) throw new PyValueError('chr() arg not in range(0x110000)');
    return String.fromCodePoint(code);
  });
  define('ord', (args) => {
    const value = args[0];
    if (typeof value === 'string') {
      const list = chars(value);
      if (list.length !== 1) {
        throw new PyTypeError(
          `ord() expected a character, but string of length ${list.length} found`,
        );
      }
      return BigInt(list[0].codePointAt(0));
    }
    if (value instanceof PyBytes && value.data.length === 1) return BigInt(value.data[0]);
    throw new PyTypeError(`ord() expected string of length 1, but ${typeName(value)} found`);
  });
  define('repr', (args) => pyRepr(args[0]));
  define('ascii', (args) => {
    const text = pyRepr(args[0]);
    return chars(text)
      .map((ch) => {
        const cp = ch.codePointAt(0);
        if (cp < 0x80) return ch;
        if (cp < 0x100) return `\\x${cp.toString(16).padStart(2, '0')}`;
        if (cp < 0x10000) return `\\u${cp.toString(16).padStart(4, '0')}`;
        return `\\U${cp.toString(16).padStart(8, '0')}`;
      })
      .join('');
  });
  define('hex', (args) => {
    const n = argInt(args[0]);
    return n < 0n ? `-0x${(-n).toString(16)}` : `0x${n.toString(16)}`;
  });
  define('oct', (args) => {
    const n = argInt(args[0]);
    return n < 0n ? `-0o${(-n).toString(8)}` : `0o${n.toString(8)}`;
  });
  define('bin', (args) => {
    const n = argInt(args[0]);
    return n < 0n ? `-0b${(-n).toString(2)}` : `0b${n.toString(2)}`;
  });
  define('round', (args) => roundValue(args));
  define('divmod', (args) => {
    const [a, b] = args;
    if (isInt(a) && isInt(b)) {
      if (asInt(b) === 0n) throw new PyZeroDivisionError('integer division or modulo by zero');
      return new PyTuple([bigFloorDiv(asInt(a), asInt(b)), bigMod(asInt(a), asInt(b))]);
    }
    return new PyTuple([numericBinary('//', a, b), numericBinary('%', a, b)]);
  });
  define('pow', (args) => {
    if (args.length > 2) {
      const [base, exponent, modulus] = args.map((arg) => asInt(arg));
      let result = 1n;
      let b = bigMod(base, modulus);
      let e = exponent;
      while (e > 0n) {
        if (e & 1n) result = bigMod(result * b, modulus);
        b = bigMod(b * b, modulus);
        e >>= 1n;
      }
      return result;
    }
    return numericBinary('**', args[0], args[1]);
  });
  define('iter', (args) => new PyIterator(pyIter(args[0]), 'iterator'));
  define('next', (args) => {
    const iterator = args[0];
    if (!(iterator instanceof PyIterator)) {
      throw new PyTypeError(`'${typeName(iterator)}' object is not an iterator`);
    }
    const step = iterator.next();
    if (step.done) {
      if (args.length > 1) return args[1];
      throw new PyStopIteration('');
    }
    return step.value;
  });
  define('id', (args) => BigInt(parseInt(fakeAddress(args[0] ?? {}).slice(2), 16)));
  define('hash', (args) => {
    const value = pyHash(args[0]);
    // str/bytes hashes are randomised in CPython; any stable value is as good.
    return value === null ? 0n : value;
  });
  define('callable', (args) => args[0] instanceof PyBuiltin || args[0] instanceof PyType || typeName(args[0]) === 'function');
  define('format', (args) => formatValue(args[0], args.length > 1 ? pyStr(args[1]) : ''));
  define('isinstance', (args) => {
    const [value, target] = args;
    const targets = target instanceof PyTuple ? target.items : [target];
    return targets.some((entry) => {
      if (!(entry instanceof PyType)) return false;
      if (entry.name === 'object') return true;
      if (entry.name === 'int') return isInt(value) && typeof value !== 'boolean' ? true : typeof value === 'boolean';
      if (entry.name === 'float') return typeof value === 'number';
      if (entry.name === 'bool') return typeof value === 'boolean';
      return typeName(value) === entry.name;
    });
  });
  define('type', (args) => {
    const name = typeName(args[0]);
    return table.get(name) instanceof PyType ? table.get(name) : new PyType(name, () => null);
  });
  define('slice', (args) => {
    if (args.length === 1) return new PySlice(null, args[0], null);
    return new PySlice(args[0], args[1], args.length > 2 ? args[2] : null);
  });
  define('memoryview', (args) => new PyMemoryView(args[0]));

  defineType('int', (args) => toInteger(args));
  defineType('float', (args) => toFloatValue(args));
  defineType('bool', (args) => (args.length === 0 ? false : truthy(args[0])));
  defineType('str', (args) => (args.length === 0 ? '' : pyStr(args[0])));
  defineType('bytes', (args) => makeBytes(args));
  defineType('bytearray', (args) => new PyByteArray(makeBytes(args).data));
  defineType('list', (args) => new PyList(args.length === 0 ? [] : iterateAll(args[0])));
  defineType('tuple', (args) => new PyTuple(args.length === 0 ? [] : iterateAll(args[0])));
  defineType('set', (args) => new PySet(args.length === 0 ? [] : setElementOrder(iterateAll(args[0])), false));
  defineType('frozenset', (args) => new PySet(args.length === 0 ? [] : setElementOrder(iterateAll(args[0])), true));
  defineType('dict', (args, kwargs) => makeDict(args, kwargs));
  defineType('range', (args) => makeRange(args));
  defineType('complex', (args) => {
    if (args.length === 0) return new PyComplex(0, 0);
    const real = args[0];
    const imag = args.length > 1 ? args[1] : 0;
    if (typeof real === 'string') {
      const text = real.trim();
      const match = /^([+-]?[\d.]+(?:[eE][+-]?\d+)?)?\s*(?:([+-])\s*([\d.]*(?:[eE][+-]?\d+)?)j)?$/.exec(text);
      if (match === null) throw new PyValueError('complex() arg is a malformed string');
      const realPart = match[1] === undefined ? 0 : Number(match[1]);
      const imagPart =
        match[2] === undefined ? 0 : Number(`${match[2]}${match[3] === '' ? '1' : match[3]}`);
      return new PyComplex(realPart, imagPart);
    }
    const base = real instanceof PyComplex ? real : new PyComplex(toFloat(real), 0);
    const extra = imag instanceof PyComplex ? imag : new PyComplex(toFloat(imag), 0);
    return new PyComplex(base.real - extra.imag, base.imag + extra.real);
  });
  defineType('object', () => null);
  defineType('type', (args) => table.get('type'));

  table.set('True', true);
  table.set('False', false);
  table.set('None', null);
  table.set('Ellipsis', ELLIPSIS);
  table.set('NotImplemented', NOT_IMPLEMENTED);
  table.set('__name__', 'builtins');

  return table;
}

function extremum(args, kwargs, interp, op) {
  const key = kwargs.get('key') ?? null;
  const items = args.length === 1 ? iterateAll(args[0]) : args;
  if (items.length === 0) {
    if (kwargs.has('default')) return kwargs.get('default');
    throw new PyValueError(`${op === '<' ? 'min' : 'max'}() iterable argument is empty`);
  }
  let best = items[0];
  let bestKey = key === null ? best : interp.call(key, [best]);
  for (const item of items.slice(1)) {
    const itemKey = key === null ? item : interp.call(key, [item]);
    if (truthy(compareOp(op, itemKey, bestKey))) {
      best = item;
      bestKey = itemKey;
    }
  }
  return best;
}
